import org.apache.pdfbox.Loader;
import org.apache.pdfbox.pdmodel.*;
import org.apache.pdfbox.pdmodel.common.PDRectangle;
import org.apache.pdfbox.text.*;
import java.io.File;
import java.util.*;

public class Probe {
    public static void main(String[] a) throws Exception {
        try (PDDocument doc = Loader.loadPDF(new File(a[0]))) {
            PDPage p = doc.getPage(0);
            System.out.println("cropbox=" + p.getCropBox() + " mediabox=" + p.getMediaBox() + " rot=" + p.getRotation());
            PDFTextStripper s = new PDFTextStripper() {
                int n = 0;
                @Override protected void processTextPosition(TextPosition t) {
                    if (n++ < 40) {
                        System.out.printf("'%s' x=%.2f y=%.2f xAdj=%.2f yAdj=%.2f w=%.2f h=%.2f hDir=%.2f fs=%.2f endY=%.2f%n",
                          t.getUnicode(), t.getX(), t.getY(), t.getXDirAdj(), t.getYDirAdj(), t.getWidth(), t.getHeight(), t.getHeightDir(), t.getFontSize(), t.getEndY());
                    }
                }
            };
            s.setSortByPosition(true);
            s.setStartPage(1); s.setEndPage(1);
            s.getText(doc);
        }
    }
}
EOF
