                double w = s[2]-s[0], ht = s[3]-s[1];
                if (ht <= 2.0 && w > 20) h++;
                else if (w <= 2.0 && ht > 5) v++;
                else if (w > 8 && ht > 5) b++;
              }
              if (h+v+b > bt) { bt=h+v+b; best=i; bh=h; bv=v; bb=b; }
            }
            System.out.printf("%-70s page=%d hlines=%d vlines=%d boxes=%d%n", f.replace("/app/src/test/resources/pdf-samples-latest/",""), best, bh, bv, bb);
          } catch (Throwable t) { System.out.println(f + " ERR " + t); }
        }
    }
}
