package com.finboost.bank.statement.parser.representation.document.extraction;

import java.util.Collection;
import java.util.EnumSet;
import java.util.Set;

/**
 * Indicates how the transaction table of a statement (or of an account, when aggregated across the
 * statements that belong to it) has been extracted.
 *
 * <ul>
 *     <li>{@link #NATIVE} - the offline/native transaction table extraction produced the tables and
 *     no remote ML extraction was invoked at all.</li>
 *     <li>{@link #ML} - the remote ML layout extraction was used because the layout is not part of
 *     the supported native bank-format families.</li>
 *     <li>{@link #NATIVE_FALLBACK_ML} - a supported native layout was attempted but did not yield a
 *     usable transaction table, so the remote ML extraction was used as a fallback.</li>
 *     <li>{@link #MIXED} - aggregation only value, used when the statements grouped under a single
 *     account did not all use the same extraction mode.</li>
 * </ul>
 */
public enum TransactionExtractionMode {

    NATIVE,
    ML,
    NATIVE_FALLBACK_ML,
    MIXED;

    /**
     * Aggregates the modes of several statements into a single account level mode.
     *
     * @param modes the per statement modes, {@code null} entries are ignored
     * @return {@code null} when nothing could be determined, the single mode when all statements
     * agree, otherwise {@link #MIXED}
     */
    public static TransactionExtractionMode aggregate(Collection<TransactionExtractionMode> modes) {
        if (modes == null || modes.isEmpty()) {
            return null;
        }

        Set<TransactionExtractionMode> distinct = EnumSet.noneOf(TransactionExtractionMode.class);
        for (TransactionExtractionMode mode : modes) {
            if (mode != null) {
                distinct.add(mode);
            }
        }

        if (distinct.isEmpty()) {
            return null;
        }
        if (distinct.size() == 1) {
            return distinct.iterator().next();
        }
        return MIXED;
    }
}

package com.finboost.bank.statement.parser.representation.document.extraction;

/**
 * The families of native (offline) transaction table layouts that can be reconstructed directly from
 * the electronic PDF content stream, without calling a remote ML layout model.
 */
public enum NativeTableLayout {

    /**
     * The transaction table is drawn with a full ruling grid: long horizontal and vertical strokes
     * (or hair-thin filled rectangles) whose intersections define every cell.
     */
    BORDERED_GRID,

    /**
     * Every transaction cell is drawn as its own rectangle (a "box"). Rows and columns are recovered
     * by grouping those boxes instead of by intersecting rulings.
     */
    BOX_GUIDED,

    /**
     * The statement has no usable vector geometry for the transaction table. Rows are selected from
     * the text layer (a row starts where a transaction date is found) and columns are derived from
     * the vertical whitespace corridors shared by the selected rows.
     */
    TEXT_ALIGNED_ROW_SELECTED
}

