package com.finboost.bank.statement.parser.service.document.extraction.nativetable;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * An axis aligned rectangle expressed in inches with a top-left origin (y grows downwards), i.e. the
 * same coordinate space that {@link com.finboost.bank.statement.parser.representation.document.extraction.Word}
 * polygons use.
 */
@Data
@AllArgsConstructor
@NoArgsConstructor
public class NativeBox {

    private float left;
    private float top;
    private float right;
    private float bottom;

    public static NativeBox of(float x1, float y1, float x2, float y2) {
        return new NativeBox(Math.min(x1, x2), Math.min(y1, y2), Math.max(x1, x2), Math.max(y1, y2));
    }

    public float width() {
        return right - left;
    }

    public float height() {
        return bottom - top;
    }

    public float centerX() {
        return (left + right) / 2f;
    }

    public float centerY() {
        return (top + bottom) / 2f;
    }

    public boolean contains(float x, float y) {
        return x >= left && x <= right && y >= top && y <= bottom;
    }

    public NativeBox union(NativeBox other) {
        if (other == null) {
            return this;
        }
        return new NativeBox(
                Math.min(this.left, other.left),
                Math.min(this.top, other.top),
                Math.max(this.right, other.right),
                Math.max(this.bottom, other.bottom));
    }

    /**
     * Vertical overlap between this box and the given band, in inches.
     */
    public float verticalOverlap(float bandTop, float bandBottom) {
        return Math.min(this.bottom, bandBottom) - Math.max(this.top, bandTop);
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativetable;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * A single axis aligned table ruling (border stroke) in inches, top-left origin.
 *
 * <p>For a horizontal ruling {@code position} is the {@code y} coordinate and {@code start}/{@code end}
 * are the {@code x} extents. For a vertical ruling it is the other way around.</p>
 */
@Data
@AllArgsConstructor
@NoArgsConstructor
public class NativeRuling {

    private float position;
    private float start;
    private float end;
    private boolean horizontal;

    public static NativeRuling horizontal(float y, float x1, float x2) {
        return new NativeRuling(y, Math.min(x1, x2), Math.max(x1, x2), true);
    }

    public static NativeRuling vertical(float x, float y1, float y2) {
        return new NativeRuling(x, Math.min(y1, y2), Math.max(y1, y2), false);
    }

    public float length() {
        return end - start;
    }

    /**
     * Overlap of this ruling's extent with the given range, in inches. Negative when disjoint.
     */
    public float overlap(float rangeStart, float rangeEnd) {
        return Math.min(this.end, rangeEnd) - Math.max(this.start, rangeStart);
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativetable;

import com.finboost.bank.statement.parser.representation.document.extraction.Word;
import lombok.Data;

import java.util.ArrayList;
import java.util.List;

/**
 * The raw native content of a single PDF page: its text layer expressed as
 * {@link Word}s plus the vector geometry (rulings and boxes) that the page draws.
 *
 * <p>All coordinates are in inches with a top-left origin so that the resulting tables are
 * interchangeable with the ones produced by the remote ML layout model.</p>
 */
@Data
public class NativePdfPage {

    private int pageNumber;
    private float width;
    private float height;
    private String textContent = "";
    private List<Word> words = new ArrayList<>();
    private List<NativeRuling> horizontalRulings = new ArrayList<>();
    private List<NativeRuling> verticalRulings = new ArrayList<>();
    private List<NativeBox> boxes = new ArrayList<>();

    public boolean hasText() {
        return words != null && !words.isEmpty();
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativetable;

import lombok.extern.slf4j.Slf4j;
import org.apache.pdfbox.contentstream.PDFGraphicsStreamEngine;
import org.apache.pdfbox.cos.COSName;
import org.apache.pdfbox.pdmodel.PDPage;
import org.apache.pdfbox.pdmodel.common.PDRectangle;
import org.apache.pdfbox.pdmodel.graphics.image.PDImage;

import java.awt.geom.Point2D;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;

/**
 * Collects the axis aligned vector geometry of a PDF page - table rulings and cell boxes - straight
 * from the content stream, so that transaction tables can be reconstructed offline.
 *
 * <p>Everything is normalised to inches with a top-left origin, matching the coordinate space used by
 * {@link com.finboost.bank.statement.parser.representation.document.extraction.Word} polygons.</p>
 */
@Slf4j
public class PdfVectorGeometryCollector extends PDFGraphicsStreamEngine {

    private static final float POINTS_PER_INCH = 72.0f;

    /** Rectangles thinner than this are border strokes rather than cells. */
    private static final float THIN_MAX_INCHES = 0.030f;
    /** Ignore geometry noise (dots, tiny marks). */
    private static final float MIN_RULING_LENGTH_INCHES = 0.04f;
    /** A cell box must be at least this wide/high to be usable. */
    private static final float MIN_BOX_WIDTH_INCHES = 0.06f;
    private static final float MIN_BOX_HEIGHT_INCHES = 0.04f;
    /** Tolerance used to decide that a stroke is axis aligned. */
    private static final float AXIS_TOLERANCE_INCHES = 0.012f;

    private final float pageWidthInches;
    private final float pageHeightInches;
    private final float offsetX;
    private final float offsetTopY;

    private final List<NativeRuling> horizontalRulings = new ArrayList<>();
    private final List<NativeRuling> verticalRulings = new ArrayList<>();
    private final List<NativeBox> boxes = new ArrayList<>();

    private final List<NativeBox> pendingRectangles = new ArrayList<>();
    private final List<float[]> pendingSegments = new ArrayList<>();

    private Point2D currentPoint;
    private Point2D subPathStart;

    public PdfVectorGeometryCollector(PDPage page) {
        super(page);
        PDRectangle cropBox = page.getCropBox();
        this.pageWidthInches = cropBox.getWidth() / POINTS_PER_INCH;
        this.pageHeightInches = cropBox.getHeight() / POINTS_PER_INCH;
        this.offsetX = cropBox.getLowerLeftX();
        this.offsetTopY = cropBox.getUpperRightY();
    }

    public List<NativeRuling> getHorizontalRulings() {
        return horizontalRulings;
    }

    public List<NativeRuling> getVerticalRulings() {
        return verticalRulings;
    }

    public List<NativeBox> getBoxes() {
        return boxes;
    }

    public float getPageWidthInches() {
        return pageWidthInches;
    }

    public float getPageHeightInches() {
        return pageHeightInches;
    }

    // ---------------------------------------------------------------------
    // Path construction
    // ---------------------------------------------------------------------

    @Override
    public void appendRectangle(Point2D p0, Point2D p1, Point2D p2, Point2D p3) {
        float x1 = toInchesX(p0.getX());
        float y1 = toInchesY(p0.getY());
        float x2 = toInchesX(p2.getX());
        float y2 = toInchesY(p2.getY());
        pendingRectangles.add(NativeBox.of(x1, y1, x2, y2));
    }

    @Override
    public void moveTo(float x, float y) {
        currentPoint = new Point2D.Float(x, y);
        subPathStart = currentPoint;
    }

    @Override
    public void lineTo(float x, float y) {
        Point2D from = currentPoint;
        currentPoint = new Point2D.Float(x, y);
        if (from == null) {
            subPathStart = currentPoint;
            return;
        }
        addPendingSegment(from, currentPoint);
    }

    @Override
    public void curveTo(float x1, float y1, float x2, float y2, float x3, float y3) {
        // Curves never take part in a table grid, only remember the new position.
        currentPoint = new Point2D.Float(x3, y3);
    }

    @Override
    public Point2D getCurrentPoint() {
        return currentPoint;
    }

    @Override
    public void closePath() {
        if (currentPoint != null && subPathStart != null) {
            addPendingSegment(currentPoint, subPathStart);
            currentPoint = subPathStart;
        }
    }

    // ---------------------------------------------------------------------
    // Path painting
    // ---------------------------------------------------------------------

    @Override
    public void strokePath() {
        flush(true);
    }

    @Override
    public void fillPath(int windingRule) {
        flush(false);
    }

    @Override
    public void fillAndStrokePath(int windingRule) {
        flush(true);
    }

    @Override
    public void endPath() {
        // "no-op" painting (usually a clipping path), the geometry must not be treated as a border.
        discardPending();
    }

    @Override
    public void clip(int windingRule) {
        // nothing to do, clipping regions are not part of the table grid
    }

    @Override
    public void drawImage(PDImage pdImage) {
        // images carry no table geometry
    }

    @Override
    public void shadingFill(COSName shadingName) {
        discardPending();
    }

    // ---------------------------------------------------------------------
    // Internals
    // ---------------------------------------------------------------------

    private void addPendingSegment(Point2D from, Point2D to) {
        pendingSegments.add(new float[]{
                toInchesX(from.getX()), toInchesY(from.getY()),
                toInchesX(to.getX()), toInchesY(to.getY())
        });
    }

    private void discardPending() {
        pendingRectangles.clear();
        pendingSegments.clear();
    }

    private void flush(boolean stroked) {
        for (float[] segment : pendingSegments) {
            registerSegment(segment[0], segment[1], segment[2], segment[3]);
        }
        pendingSegments.clear();

        for (NativeBox rectangle : pendingRectangles) {
            registerRectangle(rectangle, stroked);
        }
        pendingRectangles.clear();
    }

    private void registerSegment(float x1, float y1, float x2, float y2) {
        float dx = Math.abs(x2 - x1);
        float dy = Math.abs(y2 - y1);

        if (dy <= AXIS_TOLERANCE_INCHES && dx >= MIN_RULING_LENGTH_INCHES) {
            horizontalRulings.add(NativeRuling.horizontal((y1 + y2) / 2f, x1, x2));
        } else if (dx <= AXIS_TOLERANCE_INCHES && dy >= MIN_RULING_LENGTH_INCHES) {
            verticalRulings.add(NativeRuling.vertical((x1 + x2) / 2f, y1, y2));
        }
    }

    private void registerRectangle(NativeBox rectangle, boolean stroked) {
        float width = rectangle.width();
        float height = rectangle.height();

        boolean pageSized = width >= pageWidthInches * 0.92f && height >= pageHeightInches * 0.92f;
        if (pageSized) {
            // full page background, carries no table information
            return;
        }

        boolean thinHorizontal = height <= THIN_MAX_INCHES && width >= MIN_RULING_LENGTH_INCHES;
        boolean thinVertical = width <= THIN_MAX_INCHES && height >= MIN_RULING_LENGTH_INCHES;

        if (thinHorizontal && (!thinVertical || width >= height)) {
            horizontalRulings.add(NativeRuling.horizontal(rectangle.centerY(), rectangle.getLeft(), rectangle.getRight()));
            return;
        }
        if (thinVertical) {
            verticalRulings.add(NativeRuling.vertical(rectangle.centerX(), rectangle.getTop(), rectangle.getBottom()));
            return;
        }

        if (width < MIN_BOX_WIDTH_INCHES || height < MIN_BOX_HEIGHT_INCHES) {
            return;
        }

        boxes.add(rectangle);

        if (stroked) {
            // An outlined rectangle also contributes the four rulings of its border, which lets a
            // bordered-grid reconstruction work on statements that outline each cell.
            horizontalRulings.add(NativeRuling.horizontal(rectangle.getTop(), rectangle.getLeft(), rectangle.getRight()));
            horizontalRulings.add(NativeRuling.horizontal(rectangle.getBottom(), rectangle.getLeft(), rectangle.getRight()));
            verticalRulings.add(NativeRuling.vertical(rectangle.getLeft(), rectangle.getTop(), rectangle.getBottom()));
            verticalRulings.add(NativeRuling.vertical(rectangle.getRight(), rectangle.getTop(), rectangle.getBottom()));
        }
    }

    private float toInchesX(double x) {
        return (float) ((x - offsetX) / POINTS_PER_INCH);
    }

    private float toInchesY(double y) {
        return (float) ((offsetTopY - y) / POINTS_PER_INCH);
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativetable;

import com.finboost.bank.statement.parser.representation.document.extraction.Word;
import lombok.extern.slf4j.Slf4j;
import org.apache.pdfbox.pdmodel.PDDocument;
import org.apache.pdfbox.text.PDFTextStripper;
import org.apache.pdfbox.text.TextPosition;
import org.springframework.stereotype.Service;

import java.io.IOException;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedList;
import java.util.List;

/**
 * Rebuilds the word level text layer of an electronic PDF page using PDFBox only.
 *
 * <p>The produced {@link Word}s use the very same convention as the remote layout model - inches,
 * top-left origin, polygon ordered top-left, top-right, bottom-right, bottom-left - so that all the
 * existing post processors can consume them unchanged.</p>
 */
@Slf4j
@Service
public class NativeWordExtractor {

    private static final float POINTS_PER_INCH = 72.0f;

    /** Minimum vertical tolerance (inches) used when grouping glyphs into a text line. */
    private static final float MIN_LINE_TOLERANCE = 0.015f;
    /** Fraction of the glyph height used as vertical tolerance when grouping glyphs into a line. */
    private static final float LINE_TOLERANCE_RATIO = 0.45f;
    /** Fraction of the space width above which a horizontal gap breaks a word. */
    private static final float WORD_BREAK_SPACE_RATIO = 0.55f;

    /**
     * Extracts the words of a single page.
     *
     * @param document   an open PDF document
     * @param pageNumber the one based page number
     * @return the words of that page in reading order, never {@code null}
     */
    public List<Word> extractWords(PDDocument document, int pageNumber) throws IOException {
        GlyphCollector collector = new GlyphCollector();
        collector.setSortByPosition(false);
        collector.setStartPage(pageNumber);
        collector.setEndPage(pageNumber);
        collector.getText(document);

        return buildWords(collector.getGlyphs(), pageNumber);
    }

    /**
     * Groups the glyphs of a page into text lines and then into words.
     */
    private List<Word> buildWords(List<Glyph> glyphs, int pageNumber) {
        List<Word> words = new LinkedList<>();
        if (glyphs.isEmpty()) {
            return words;
        }

        List<List<Glyph>> lines = groupIntoLines(glyphs);

        for (List<Glyph> line : lines) {
            words.addAll(splitLineIntoWords(line, pageNumber));
        }

        // Reading order: top to bottom, then left to right.
        words.sort(Comparator
                .comparing((Word word) -> word.getY4() == null ? 0f : word.getY4())
                .thenComparing(word -> word.getX1() == null ? 0f : word.getX1()));

        int wordIndex = 1;
        for (Word word : words) {
            word.setPageIndex(pageNumber);
            word.setWordIndex(wordIndex++);
        }

        return words;
    }

    private List<List<Glyph>> groupIntoLines(List<Glyph> glyphs) {
        List<Glyph> sorted = new ArrayList<>(glyphs);
        sorted.sort(Comparator.comparingDouble((Glyph glyph) -> glyph.baseline)
                .thenComparingDouble(glyph -> glyph.left));

        List<List<Glyph>> lines = new LinkedList<>();
        List<Glyph> current = new ArrayList<>();
        float lineBaseline = 0f;

        for (Glyph glyph : sorted) {
            float tolerance = Math.max(MIN_LINE_TOLERANCE, glyph.height * LINE_TOLERANCE_RATIO);
            if (current.isEmpty()) {
                current.add(glyph);
                lineBaseline = glyph.baseline;
                continue;
            }
            if (Math.abs(glyph.baseline - lineBaseline) <= tolerance) {
                current.add(glyph);
            } else {
                lines.add(current);
                current = new ArrayList<>();
                current.add(glyph);
                lineBaseline = glyph.baseline;
            }
        }
        if (!current.isEmpty()) {
            lines.add(current);
        }

        return lines;
    }

    private List<Word> splitLineIntoWords(List<Glyph> line, int pageNumber) {
        List<Word> words = new LinkedList<>();
        line.sort(Comparator.comparingDouble(glyph -> glyph.left));

        List<Glyph> current = new ArrayList<>();
        Glyph previous = null;

        for (Glyph glyph : line) {
            if (glyph.blank) {
                flushWord(current, pageNumber, words);
                current = new ArrayList<>();
                previous = null;
                continue;
            }

            if (previous != null) {
                float gap = glyph.left - previous.right();
                float threshold = wordBreakThreshold(previous);
                if (gap > threshold) {
                    flushWord(current, pageNumber, words);
                    current = new ArrayList<>();
                }
            }
            current.add(glyph);
            previous = glyph;
        }
        flushWord(current, pageNumber, words);

        return words;
    }

    private float wordBreakThreshold(Glyph glyph) {
        if (glyph.spaceWidth > 0f) {
            return glyph.spaceWidth * WORD_BREAK_SPACE_RATIO;
        }
        return Math.max(MIN_LINE_TOLERANCE, glyph.height * 0.35f);
    }

    private void flushWord(List<Glyph> glyphs, int pageNumber, List<Word> target) {
        if (glyphs == null || glyphs.isEmpty()) {
            return;
        }

        StringBuilder content = new StringBuilder();
        float minX = Float.MAX_VALUE;
        float maxX = -Float.MAX_VALUE;
        float minY = Float.MAX_VALUE;
        float maxY = -Float.MAX_VALUE;

        for (Glyph glyph : glyphs) {
            content.append(glyph.text);
            minX = Math.min(minX, glyph.left);
            maxX = Math.max(maxX, glyph.right());
            minY = Math.min(minY, glyph.top());
            maxY = Math.max(maxY, glyph.baseline);
        }

        String text = content.toString().trim();
        if (text.isEmpty()) {
            return;
        }

        Word word = new Word();
        word.setContent(text);
        word.setPageNumber(pageNumber);
        word.setX1(minX);
        word.setY1(minY);
        word.setX2(maxX);
        word.setY2(minY);
        word.setX3(maxX);
        word.setY3(maxY);
        word.setX4(minX);
        word.setY4(maxY);
        word.setWidth(maxX - minX);
        word.setHeight(maxY - minY);
        word.setPageIndex(pageNumber);

        target.add(word);
    }

    /**
     * A single glyph with its box already converted to inches / top-left origin.
     */
    private static final class Glyph {
        private final String text;
        private final float left;
        private final float width;
        private final float height;
        private final float baseline;
        private final float spaceWidth;
        private final boolean blank;

        private Glyph(String text, float left, float width, float height, float baseline, float spaceWidth) {
            this.text = text;
            this.left = left;
            this.width = width;
            this.height = height;
            this.baseline = baseline;
            this.spaceWidth = spaceWidth;
            this.blank = text.isBlank();
        }

        private float right() {
            return left + width;
        }

        private float top() {
            return baseline - height;
        }
    }

    /**
     * Collects every glyph of a page without letting PDFBox re-assemble words, so that word
     * boundaries can be derived from real geometry instead of from the content stream order.
     */
    private static final class GlyphCollector extends PDFTextStripper {

        private final List<Glyph> glyphs = new LinkedList<>();

        private GlyphCollector() throws IOException {
            super();
        }

        private List<Glyph> getGlyphs() {
            return glyphs;
        }

        @Override
        protected void processTextPosition(TextPosition text) {
            String unicode = text.getUnicode();
            if (unicode == null || unicode.isEmpty()) {
                return;
            }

            float height = text.getHeightDir() > 0 ? text.getHeightDir() : text.getHeight();
            if (height <= 0) {
                height = text.getFontSize();
            }

            glyphs.add(new Glyph(
                    unicode,
                    text.getXDirAdj() / POINTS_PER_INCH,
                    Math.abs(text.getWidthDirAdj()) / POINTS_PER_INCH,
                    Math.abs(height) / POINTS_PER_INCH,
                    text.getYDirAdj() / POINTS_PER_INCH,
                    Math.abs(text.getWidthOfSpace()) / POINTS_PER_INCH));
        }
    }
}

