package com.finboost.bank.statement.parser.service.document.extraction.nativetable;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.LinkedList;
import java.util.List;

/**
 * Small geometry helpers shared by the native table extractors.
 */
public final class NativeGeometryUtil {

    private NativeGeometryUtil() {
    }

    /**
     * Merges rulings that lie on the same line (within {@code positionTolerance}) and whose extents
     * touch or overlap (within {@code gapTolerance}). Statements very often draw a single table border
     * as one short stroke per cell, merging them is what turns those strokes back into a grid line.
     */
    public static List<NativeRuling> mergeCollinear(List<NativeRuling> rulings,
                                                    float positionTolerance,
                                                    float gapTolerance) {
        List<NativeRuling> merged = new LinkedList<>();
        if (rulings == null || rulings.isEmpty()) {
            return merged;
        }

        List<NativeRuling> sorted = new ArrayList<>(rulings);
        sorted.sort(Comparator.comparingDouble(NativeRuling::getPosition)
                .thenComparingDouble(NativeRuling::getStart));

        List<NativeRuling> band = new ArrayList<>();
        float bandPosition = sorted.get(0).getPosition();

        for (NativeRuling ruling : sorted) {
            if (band.isEmpty() || Math.abs(ruling.getPosition() - bandPosition) <= positionTolerance) {
                band.add(ruling);
                continue;
            }
            merged.addAll(mergeBand(band, gapTolerance));
            band = new ArrayList<>();
            band.add(ruling);
            bandPosition = ruling.getPosition();
        }
        merged.addAll(mergeBand(band, gapTolerance));

        return merged;
    }

    private static List<NativeRuling> mergeBand(List<NativeRuling> band, float gapTolerance) {
        List<NativeRuling> merged = new LinkedList<>();
        if (band.isEmpty()) {
            return merged;
        }

        band.sort(Comparator.comparingDouble(NativeRuling::getStart));

        boolean horizontal = band.get(0).isHorizontal();
        float positionSum = 0f;
        float start = band.get(0).getStart();
        float end = band.get(0).getEnd();
        int count = 0;

        for (NativeRuling ruling : band) {
            if (ruling.getStart() - end <= gapTolerance) {
                end = Math.max(end, ruling.getEnd());
                positionSum += ruling.getPosition();
                count++;
            } else {
                merged.add(new NativeRuling(positionSum / Math.max(count, 1), start, end, horizontal));
                start = ruling.getStart();
                end = ruling.getEnd();
                positionSum = ruling.getPosition();
                count = 1;
            }
        }
        merged.add(new NativeRuling(positionSum / Math.max(count, 1), start, end, horizontal));

        return merged;
    }

    /**
     * Collapses nearby coordinates into a single representative value (the mean of the cluster).
     *
     * @return the cluster representatives in ascending order
     */
    public static List<Float> clusterPositions(List<Float> positions, float tolerance) {
        List<Float> clustered = new LinkedList<>();
        if (positions == null || positions.isEmpty()) {
            return clustered;
        }

        List<Float> sorted = new ArrayList<>(positions);
        Collections.sort(sorted);

        float sum = sorted.get(0);
        int count = 1;
        float reference = sorted.get(0);

        for (int i = 1; i < sorted.size(); i++) {
            float value = sorted.get(i);
            if (value - reference <= tolerance) {
                sum += value;
                count++;
            } else {
                clustered.add(sum / count);
                sum = value;
                count = 1;
                reference = value;
            }
        }
        clustered.add(sum / count);

        return clustered;
    }

    /**
     * Finds the band index of {@code value} inside an ascending list of boundaries.
     *
     * @return the index in {@code [0, boundaries.size() - 2]} or {@code -1} when outside
     */
    public static int bandIndex(List<Float> boundaries, float value) {
        if (boundaries == null || boundaries.size() < 2) {
            return -1;
        }
        for (int i = 0; i < boundaries.size() - 1; i++) {
            float low = boundaries.get(i);
            float high = boundaries.get(i + 1);
            if (value >= low && value < high) {
                return i;
            }
        }
        // include the very last boundary in the last band
        float last = boundaries.get(boundaries.size() - 1);
        if (Math.abs(value - last) < 1e-4f) {
            return boundaries.size() - 2;
        }
        return -1;
    }

    /**
     * Index of the boundary closest to {@code value}.
     */
    public static int nearestBoundaryIndex(List<Float> boundaries, float value) {
        int best = -1;
        float bestDistance = Float.MAX_VALUE;
        for (int i = 0; i < boundaries.size(); i++) {
            float distance = Math.abs(boundaries.get(i) - value);
            if (distance < bestDistance) {
                bestDistance = distance;
                best = i;
            }
        }
        return best;
    }

    /**
     * Median of the given values, {@code fallback} when the list is empty.
     */
    public static float median(List<Float> values, float fallback) {
        if (values == null || values.isEmpty()) {
            return fallback;
        }
        List<Float> sorted = new ArrayList<>(values);
        Collections.sort(sorted);
        return sorted.get(sorted.size() / 2);
    }
}

