/**
 * An intermediate cell produced by a native table extractor before it is turned into a
 * {@link com.finboost.bank.statement.parser.representation.document.extraction.TableCell}.
 */
@Data
public class NativeCell {

    private int rowIndex;
    private int columnIndex;
    private NativeBox box;

    /**
     * Words already attributed to this cell by the extractor. When {@code null} the assembler
     * attributes the page words geometrically.
     */
    private List<Word> words;

    public NativeCell(int rowIndex, int columnIndex, NativeBox box) {
        this.rowIndex = rowIndex;
        this.columnIndex = columnIndex;
        this.box = box;
