package com.finboost.bank.statement.parser.service.document.extraction.nativetable;

import com.finboost.bank.statement.parser.representation.document.extraction.ColumnDataType;
import com.finboost.bank.statement.parser.representation.document.extraction.ColumnTransactionType;
import com.finboost.bank.statement.parser.representation.document.extraction.Table;
import com.finboost.bank.statement.parser.representation.document.extraction.TableCell;
import com.finboost.bank.statement.parser.representation.document.extraction.Word;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.LinkedList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

/**
 * Turns the intermediate cells of a native extractor into a
 * {@link Table} that is byte-for-byte compatible with what the remote layout
 * model produces, so every downstream post processor keeps working unchanged.
 */
public final class NativeTableAssembler {

    private NativeTableAssembler() {
    }

    /**
     * @param pageNumber       the one based page number
     * @param cells            the intermediate cells, row/column indexes need not be contiguous
     * @param pageWords        every word of the page, used when a cell has no pre-assigned words
     * @param columnBoundaries the column boundaries in inches, may be {@code null}
     * @return the assembled table or {@code null} when nothing usable is left after pruning
     */
    public static Table assemble(int pageNumber,
                                 List<NativeCell> cells,
                                 List<Word> pageWords,
                                 List<Float> columnBoundaries) {
        if (cells == null || cells.isEmpty()) {
            return null;
        }

        Map<Integer, Map<Integer, NativeCell>> grid = new TreeMap<>();
        for (NativeCell cell : cells) {
            grid.computeIfAbsent(cell.getRowIndex(), key -> new TreeMap<>())
                    .putIfAbsent(cell.getColumnIndex(), cell);
        }

        attachWords(grid, pageWords);
        pruneEmptyRows(grid);

        if (grid.isEmpty()) {
            return null;
        }

        Map<Integer, Map<Integer, TableCell>> tableCells = new LinkedHashMap<>();
        int rowIndex = 0;
        int maxColumn = -1;
        NativeBox tableBox = null;

        for (Map<Integer, NativeCell> row : grid.values()) {
            Map<Integer, TableCell> tableRow = new LinkedHashMap<>();
            for (Map.Entry<Integer, NativeCell> entry : row.entrySet()) {
                NativeCell nativeCell = entry.getValue();
                tableRow.put(entry.getKey(), toTableCell(nativeCell, rowIndex, entry.getKey()));
                maxColumn = Math.max(maxColumn, entry.getKey());
                tableBox = nativeCell.getBox() == null ? tableBox
                        : (tableBox == null ? nativeCell.getBox() : tableBox.union(nativeCell.getBox()));
            }
            tableCells.put(rowIndex, tableRow);
            rowIndex++;
        }

        if (tableBox == null) {
            return null;
        }

        Table table = new Table();
        table.setPageNumber(pageNumber);
        table.setX1(tableBox.getLeft());
        table.setY1(tableBox.getTop());
        table.setX2(tableBox.getRight());
        table.setY2(tableBox.getTop());
        table.setX3(tableBox.getRight());
        table.setY3(tableBox.getBottom());
        table.setX4(tableBox.getLeft());
        table.setY4(tableBox.getBottom());
        table.setCells(tableCells);
        table.setTotalRows(tableCells.size());
        table.setTotalColumns(maxColumn + 1);
        table.setSpanOffset(0);
        table.setSpanLength(0);
        table.setColType(new ArrayList<ColumnDataType>());
        table.setTxnColType(new ArrayList<ColumnTransactionType>());
        table.setColumnBoundaries(columnBoundaries == null ? new ArrayList<>() : new ArrayList<>(columnBoundaries));
        table.setBankTransactions(false);

        return table;
    }

    private static TableCell toTableCell(NativeCell nativeCell, int rowIndex, int columnIndex) {
        NativeBox box = nativeCell.getBox();
        TableCell cell = new TableCell();
        cell.setRowindex(rowIndex);
        cell.setColindex(columnIndex);
        cell.setRowspan(1);
        cell.setColspan(1);
        cell.setHeaderOrFooterCell(false);
        cell.setX1(box.getLeft());
        cell.setY1(box.getTop());
        cell.setX2(box.getRight());
        cell.setY2(box.getTop());
        cell.setX3(box.getRight());
        cell.setY3(box.getBottom());
        cell.setX4(box.getLeft());
        cell.setY4(box.getBottom());

        List<Word> words = nativeCell.getWords() == null ? new LinkedList<>() : nativeCell.getWords();
        words.sort(Comparator
                .comparing((Word word) -> word.getY4() == null ? 0f : word.getY4())
                .thenComparing(word -> word.getX1() == null ? 0f : word.getX1()));
        cell.setWords(words);

        return cell;
    }

    /**
     * Attributes every page word to the cell that geometrically contains its centre, but only for the
     * cells that have not been filled in by the extractor already.
     */
    private static void attachWords(Map<Integer, Map<Integer, NativeCell>> grid, List<Word> pageWords) {
        List<NativeCell> pending = new LinkedList<>();
        for (Map<Integer, NativeCell> row : grid.values()) {
            for (NativeCell cell : row.values()) {
                if (cell.getWords() == null) {
                    cell.setWords(new LinkedList<>());
                    pending.add(cell);
                }
            }
        }

        if (pending.isEmpty() || pageWords == null || pageWords.isEmpty()) {
            return;
        }

        for (Word word : pageWords) {
            if (word.getX1() == null || word.getY1() == null) {
                continue;
            }
            float centerX = (word.getX1() + word.getX3()) / 2f;
            float centerY = (word.getY1() + word.getY3()) / 2f;

            for (NativeCell cell : pending) {
                NativeBox box = cell.getBox();
                if (box != null && box.contains(centerX, centerY)) {
                    cell.getWords().add(word);
                    break;
                }
            }
        }
    }

    /**
     * Removes rows in which no cell holds any text - typically the spacing rows of a ruled grid.
     */
    private static void pruneEmptyRows(Map<Integer, Map<Integer, NativeCell>> grid) {
        grid.entrySet().removeIf(entry -> {
            for (NativeCell cell : entry.getValue().values()) {
                if (cell.getWords() != null && !cell.getWords().isEmpty()) {
                    return false;
                }
            }
            return true;
        });
    }
}

