package com.finboost.bank.statement.parser.service.document.extraction.nativetable;

import com.finboost.bank.statement.parser.representation.document.extraction.NativeTableLayout;
import lombok.Data;

import java.util.Collections;
import java.util.List;

/**
 * The native extraction policy of one bank-format family: which native layouts to try, in which
 * order, and the shape a reconstructed transaction table must have to be accepted.
 */
@Data
public class NativeExtractionPolicy {

    /** The normalised bank code this policy belongs to. */
    private final String bankCode;

    /** Native layouts to try, in priority order. */
    private final List<NativeTableLayout> candidateLayouts;

    /** A reconstructed transaction table needs at least this many columns. */
    private final int minimumColumns;

    /** A reconstructed transaction table needs at least this many rows (header included). */
    private final int minimumRows;

    /**
     * Vertical distance (inches) above which two consecutive row bands are considered to belong to two
     * different tables rather than to one table with a tall row.
     */
    private final float maximumRowGap;

    public NativeExtractionPolicy(String bankCode,
                                  List<NativeTableLayout> candidateLayouts,
                                  int minimumColumns,
                                  int minimumRows,
                                  float maximumRowGap) {
        this.bankCode = bankCode;
        this.candidateLayouts = candidateLayouts == null
                ? Collections.<NativeTableLayout>emptyList()
                : List.copyOf(candidateLayouts);
        this.minimumColumns = minimumColumns;
        this.minimumRows = minimumRows;
        this.maximumRowGap = maximumRowGap;
    }

    public static NativeExtractionPolicy of(String bankCode, List<NativeTableLayout> layouts) {
        return new NativeExtractionPolicy(bankCode, layouts, 4, 3, 0.9f);
    }

    public boolean supports(NativeTableLayout layout) {
        return candidateLayouts.contains(layout);
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativetable;

import com.finboost.bank.statement.parser.representation.document.extraction.NativeTableLayout;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Component;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

import static com.finboost.bank.statement.parser.representation.document.extraction.NativeTableLayout.BORDERED_GRID;
import static com.finboost.bank.statement.parser.representation.document.extraction.NativeTableLayout.BOX_GUIDED;
import static com.finboost.bank.statement.parser.representation.document.extraction.NativeTableLayout.TEXT_ALIGNED_ROW_SELECTED;

/**
 * Selects the native extraction policy of a bank-format family.
 *
 * <p>The supported families are the ones covered by the statement fixture corpus under
 * {@code src/test/resources/pdf-samples-latest}. Each family is registered with the native layouts its
 * formats actually use, in the order in which they should be attempted:</p>
 *
 * <ul>
 *     <li>{@link NativeTableLayout#BORDERED_GRID} for statements that draw a full ruling grid,</li>
 *     <li>{@link NativeTableLayout#BOX_GUIDED} for statements that draw one rectangle per cell,</li>
 *     <li>{@link NativeTableLayout#TEXT_ALIGNED_ROW_SELECTED} for statements without usable table
 *     geometry, where the rows have to be selected from the text layer.</li>
 * </ul>
 *
 * <p>Bank codes that are not registered here are deliberately left to the remote ML extraction.</p>
 */
@Slf4j
@Component
public class NativeExtractionPolicyRegistry {

    private final Map<String, NativeExtractionPolicy> policiesByBankCode;

    public NativeExtractionPolicyRegistry() {
        Map<String, NativeExtractionPolicy> policies = new LinkedHashMap<>();

        // Ruled grid families.
        register(policies, "BANDHAN", List.of(BORDERED_GRID));
        register(policies, "FEDERAL", List.of(BORDERED_GRID));
        register(policies, "IDBI", List.of(BORDERED_GRID));
        register(policies, "IDFC", List.of(BORDERED_GRID));
        register(policies, "STANDARD_CHARTERED", List.of(BORDERED_GRID));
        register(policies, "YES", List.of(BORDERED_GRID));
        register(policies, "BOB", List.of(BORDERED_GRID, BOX_GUIDED));
        register(policies, "PNB", List.of(BORDERED_GRID, BOX_GUIDED));
        register(policies, "INDUSIND", List.of(BORDERED_GRID, BOX_GUIDED));
        register(policies, "SURYODAY_SMALL_FINANCE_BANK_LTD", List.of(BORDERED_GRID, BOX_GUIDED));
        register(policies, "TJSB_BANK", List.of(BORDERED_GRID, BOX_GUIDED));
        register(policies, "HDFC", List.of(BORDERED_GRID, BOX_GUIDED, TEXT_ALIGNED_ROW_SELECTED));
        register(policies, "UNION", List.of(BORDERED_GRID, BOX_GUIDED, TEXT_ALIGNED_ROW_SELECTED));
        register(policies, "GS_MAHANAGAR_CO_OP_BANK", List.of(BORDERED_GRID, TEXT_ALIGNED_ROW_SELECTED));

        // Box (one rectangle per cell) families.
        register(policies, "AHMEDNAGAR", List.of(BOX_GUIDED));
        register(policies, "CITI", List.of(BOX_GUIDED));
        register(policies, "DEUSTCHE", List.of(BOX_GUIDED));
        register(policies, "INDIAN", List.of(BOX_GUIDED));
        register(policies, "INDIAN_OVERSEAS", List.of(BOX_GUIDED));
        register(policies, "AXIS", List.of(BOX_GUIDED, BORDERED_GRID));
        register(policies, "ICICI", List.of(BOX_GUIDED, BORDERED_GRID));
        register(policies, "RBL", List.of(BOX_GUIDED, BORDERED_GRID));
        register(policies, "SBI", List.of(BOX_GUIDED, BORDERED_GRID));

        // Families whose formats include text aligned statements without table geometry.
        register(policies, "CBI", List.of(BOX_GUIDED, TEXT_ALIGNED_ROW_SELECTED));
        register(policies, "KOTAK", List.of(BOX_GUIDED, TEXT_ALIGNED_ROW_SELECTED));

        this.policiesByBankCode = Collections.unmodifiableMap(policies);
    }

    private static void register(Map<String, NativeExtractionPolicy> policies,
                                 String bankCode,
                                 List<NativeTableLayout> layouts) {
        policies.put(bankCode, NativeExtractionPolicy.of(bankCode, layouts));
    }

    /**
     * @param bankCode the bank code of the statement, may be {@code null}
     * @return the policy of the matching bank-format family, or {@code null} when the family is not
     * supported natively and the remote ML extraction has to be used
     */
    public NativeExtractionPolicy findPolicy(String bankCode) {
        String normalised = normalise(bankCode);
        if (normalised == null) {
            return null;
        }
        NativeExtractionPolicy policy = policiesByBankCode.get(normalised);
        if (policy == null) {
            log.debug("No native transaction table policy registered for bank code {}", normalised);
        }
        return policy;
    }

    public boolean isSupported(String bankCode) {
        return findPolicy(bankCode) != null;
    }

    /**
     * Normalises a bank code so that fixture folder names, client supplied codes and configured codes
     * all resolve to the same family key.
     */
    static String normalise(String bankCode) {
        if (bankCode == null) {
            return null;
        }
        String normalised = bankCode.trim().toUpperCase().replaceAll("[^A-Z0-9]+", "_");
        normalised = normalised.replaceAll("^_+", "").replaceAll("_+$", "");
        return normalised.isEmpty() ? null : normalised;
    }
}

