package com.finboost.bank.statement.parser.service.document.extraction.nativetable;

import com.finboost.bank.statement.parser.representation.document.extraction.NativeTableLayout;
import com.finboost.bank.statement.parser.representation.document.extraction.Table;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;

import java.util.ArrayList;
import java.util.LinkedList;
import java.util.List;

/**
 * Rebuilds transaction tables from the ruling grid drawn by the statement.
 *
 * <p>Statements of this family draw the table borders either as strokes or as hair-thin filled
 * rectangles, very often one short stroke per cell edge. The extractor therefore
 * <ol>
 *     <li>merges collinear strokes back into full grid lines,</li>
 *     <li>splits the page into grids separated by large vertical gaps,</li>
 *     <li>keeps the horizontal lines that span most of the grid as row boundaries and the vertical
 *     lines that span a significant part of the grid height as column boundaries,</li>
 *     <li>materialises one cell per (row band, column band) pair.</li>
 * </ol>
 */
@Slf4j
@Service
public class BorderedGridTableExtractor implements NativeTableExtractor {

    private static final float POSITION_TOLERANCE = 0.022f;
    private static final float SEGMENT_GAP_TOLERANCE = 0.06f;
    /** A horizontal line must cover this fraction of the grid width to act as a row boundary. */
    private static final float ROW_LINE_COVERAGE = 0.55f;
    /** A vertical line must cover this fraction of the grid height to act as a column boundary. */
    private static final float COLUMN_LINE_COVERAGE = 0.25f;
    private static final float MIN_ROW_HEIGHT = 0.045f;
    private static final float MIN_COLUMN_WIDTH = 0.10f;

    @Override
    public NativeTableLayout getLayout() {
        return NativeTableLayout.BORDERED_GRID;
    }

    @Override
    public List<Table> extractTables(NativePdfPage page, NativeExtractionPolicy policy) {
        List<Table> tables = new LinkedList<>();
        if (page == null || !page.hasText()) {
            return tables;
        }

        List<NativeRuling> horizontal = NativeGeometryUtil.mergeCollinear(
                page.getHorizontalRulings(), POSITION_TOLERANCE, SEGMENT_GAP_TOLERANCE);
        List<NativeRuling> vertical = NativeGeometryUtil.mergeCollinear(
                page.getVerticalRulings(), POSITION_TOLERANCE, SEGMENT_GAP_TOLERANCE);

        if (horizontal.size() < policy.getMinimumRows() || vertical.size() < 2) {
            return tables;
        }

        for (List<NativeRuling> gridRows : splitIntoGrids(horizontal, policy.getMaximumRowGap())) {
            Table table = buildTable(page, gridRows, vertical, policy);
            if (table != null) {
                tables.add(table);
            }
        }

        return tables;
    }

    /**
     * Splits the horizontal lines of a page into separate grids whenever two consecutive lines are
     * further apart than the policy allows for a single row.
     */
    private List<List<NativeRuling>> splitIntoGrids(List<NativeRuling> horizontal, float maximumRowGap) {
        List<List<NativeRuling>> grids = new LinkedList<>();
        List<NativeRuling> sorted = new ArrayList<>(horizontal);
        sorted.sort((left, right) -> Float.compare(left.getPosition(), right.getPosition()));

        List<NativeRuling> current = new ArrayList<>();
        float previousPosition = Float.NaN;

        for (NativeRuling ruling : sorted) {
            if (!current.isEmpty() && ruling.getPosition() - previousPosition > maximumRowGap) {
                grids.add(current);
                current = new ArrayList<>();
            }
            current.add(ruling);
            previousPosition = ruling.getPosition();
        }
        if (!current.isEmpty()) {
            grids.add(current);
        }

        return grids;
    }

    private Table buildTable(NativePdfPage page,
                             List<NativeRuling> gridRows,
                             List<NativeRuling> verticalRulings,
                             NativeExtractionPolicy policy) {
        float gridTop = Float.MAX_VALUE;
        float gridBottom = -Float.MAX_VALUE;
        float gridLeft = Float.MAX_VALUE;
        float gridRight = -Float.MAX_VALUE;

        for (NativeRuling ruling : gridRows) {
            gridTop = Math.min(gridTop, ruling.getPosition());
            gridBottom = Math.max(gridBottom, ruling.getPosition());
            gridLeft = Math.min(gridLeft, ruling.getStart());
            gridRight = Math.max(gridRight, ruling.getEnd());
        }

        float gridWidth = gridRight - gridLeft;
        float gridHeight = gridBottom - gridTop;
        if (gridWidth <= 0 || gridHeight <= 0) {
            return null;
        }

        List<Float> rowBoundaries = collectRowBoundaries(gridRows, gridWidth);
        List<Float> columnBoundaries = collectColumnBoundaries(verticalRulings, gridTop, gridBottom, gridHeight);

        if (rowBoundaries.size() < policy.getMinimumRows() + 1 || columnBoundaries.size() < policy.getMinimumColumns() + 1) {
            return null;
        }

        List<NativeCell> cells = new LinkedList<>();
        for (int row = 0; row < rowBoundaries.size() - 1; row++) {
            float top = rowBoundaries.get(row);
            float bottom = rowBoundaries.get(row + 1);
            if (bottom - top < MIN_ROW_HEIGHT) {
                continue;
            }
            for (int column = 0; column < columnBoundaries.size() - 1; column++) {
                float left = columnBoundaries.get(column);
                float right = columnBoundaries.get(column + 1);
                cells.add(new NativeCell(row, column, new NativeBox(left, top, right, bottom)));
            }
        }

        return NativeTableAssembler.assemble(page.getPageNumber(), cells, page.getWords(), columnBoundaries);
    }

    private List<Float> collectRowBoundaries(List<NativeRuling> gridRows, float gridWidth) {
        List<Float> positions = new LinkedList<>();
        for (NativeRuling ruling : gridRows) {
            if (ruling.length() >= gridWidth * ROW_LINE_COVERAGE) {
                positions.add(ruling.getPosition());
            }
        }
        return NativeGeometryUtil.clusterPositions(positions, POSITION_TOLERANCE);
    }

    private List<Float> collectColumnBoundaries(List<NativeRuling> verticalRulings,
                                                float gridTop,
                                                float gridBottom,
                                                float gridHeight) {
        List<Float> positions = new LinkedList<>();
        for (NativeRuling ruling : verticalRulings) {
            float overlap = ruling.overlap(gridTop, gridBottom);
            if (overlap >= gridHeight * COLUMN_LINE_COVERAGE) {
                positions.add(ruling.getPosition());
            }
        }

        List<Float> clustered = NativeGeometryUtil.clusterPositions(positions, POSITION_TOLERANCE);

        // Drop boundaries that would create unusably narrow columns.
        List<Float> boundaries = new ArrayList<>();
        for (Float position : clustered) {
            if (boundaries.isEmpty() || position - boundaries.get(boundaries.size() - 1) >= MIN_COLUMN_WIDTH) {
                boundaries.add(position);
            }
        }
        return boundaries;
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativetable;

import com.finboost.bank.statement.parser.representation.document.extraction.NativeTableLayout;
import com.finboost.bank.statement.parser.representation.document.extraction.Table;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedList;
import java.util.List;

/**
 * Rebuilds transaction tables from statements that draw one rectangle per cell instead of a ruling
 * grid.
 *
 * <p>The boxes are grouped into row bands by vertical overlap, their left and right edges give the
 * column boundaries, and the resulting (row band x column band) grid is then materialised. Using the
 * boxes only as a guide - rather than as the cells themselves - keeps rows complete even when a bank
 * omits the rectangle of an empty cell.</p>
 */
@Slf4j
@Service
public class BoxGuidedTableExtractor implements NativeTableExtractor {

    private static final float EDGE_TOLERANCE = 0.05f;
    private static final float MIN_ROW_OVERLAP_RATIO = 0.5f;
    private static final float MAX_CELL_HEIGHT = 1.2f;
    private static final float MIN_COLUMN_WIDTH = 0.10f;

    @Override
    public NativeTableLayout getLayout() {
        return NativeTableLayout.BOX_GUIDED;
    }

    @Override
    public List<Table> extractTables(NativePdfPage page, NativeExtractionPolicy policy) {
        List<Table> tables = new LinkedList<>();
        if (page == null || !page.hasText()) {
            return tables;
        }

        List<NativeBox> boxes = filterCellBoxes(page);
        if (boxes.size() < policy.getMinimumColumns() * policy.getMinimumRows()) {
            return tables;
        }

        List<RowBand> rows = groupIntoRows(boxes);
        for (List<RowBand> group : splitIntoTables(rows, policy.getMaximumRowGap())) {
            Table table = buildTable(page, group, policy);
            if (table != null) {
                tables.add(table);
            }
        }

        return tables;
    }

    private List<NativeBox> filterCellBoxes(NativePdfPage page) {
        List<NativeBox> boxes = new ArrayList<>();
        float maxWidth = page.getWidth() * 0.95f;

        for (NativeBox box : page.getBoxes()) {
            if (box.width() <= 0 || box.height() <= 0) {
                continue;
            }
            if (box.width() > maxWidth || box.height() > MAX_CELL_HEIGHT) {
                continue;
            }
            if (isDuplicate(boxes, box)) {
                continue;
            }
            boxes.add(box);
        }

        boxes.sort(Comparator.comparingDouble(NativeBox::getTop).thenComparingDouble(NativeBox::getLeft));
        return boxes;
    }

    private boolean isDuplicate(List<NativeBox> boxes, NativeBox candidate) {
        for (NativeBox box : boxes) {
            if (Math.abs(box.getLeft() - candidate.getLeft()) < 0.005f
                    && Math.abs(box.getTop() - candidate.getTop()) < 0.005f
                    && Math.abs(box.getRight() - candidate.getRight()) < 0.005f
                    && Math.abs(box.getBottom() - candidate.getBottom()) < 0.005f) {
                return true;
            }
        }
        return false;
    }

    private List<RowBand> groupIntoRows(List<NativeBox> boxes) {
        List<RowBand> rows = new LinkedList<>();
        RowBand current = null;

        for (NativeBox box : boxes) {
            if (current != null && box.verticalOverlap(current.top, current.bottom) >= box.height() * MIN_ROW_OVERLAP_RATIO) {
                current.add(box);
                continue;
            }
            current = new RowBand(box);
            rows.add(current);
        }

        return rows;
    }

    private List<List<RowBand>> splitIntoTables(List<RowBand> rows, float maximumRowGap) {
        List<List<RowBand>> groups = new LinkedList<>();
        List<RowBand> current = new ArrayList<>();
        RowBand previous = null;

        for (RowBand row : rows) {
            if (previous != null && row.top - previous.bottom > maximumRowGap) {
                groups.add(current);
                current = new ArrayList<>();
            }
            current.add(row);
            previous = row;
        }
        if (!current.isEmpty()) {
            groups.add(current);
        }

        return groups;
    }

    private Table buildTable(NativePdfPage page, List<RowBand> rows, NativeExtractionPolicy policy) {
        if (rows.size() < policy.getMinimumRows()) {
            return null;
        }

        List<Float> columnBoundaries = collectColumnBoundaries(rows, policy.getMinimumColumns());
        if (columnBoundaries.size() < policy.getMinimumColumns() + 1) {
            return null;
        }

        List<NativeCell> cells = new LinkedList<>();
        for (int index = 0; index < rows.size(); index++) {
            RowBand row = rows.get(index);
            float top = row.top;
            float bottom = index + 1 < rows.size() ? Math.max(row.bottom, rows.get(index + 1).top) : row.bottom;

            for (int column = 0; column < columnBoundaries.size() - 1; column++) {
                cells.add(new NativeCell(index, column,
                        new NativeBox(columnBoundaries.get(column), top, columnBoundaries.get(column + 1), bottom)));
            }
        }

        return NativeTableAssembler.assemble(page.getPageNumber(), cells, page.getWords(), columnBoundaries);
    }

    /**
     * Derives the column boundaries from the vertical edges of the rows that actually look like body
     * rows, so that a wide title box cannot pollute the grid.
     */
    private List<Float> collectColumnBoundaries(List<RowBand> rows, int minimumColumns) {
        List<Float> edges = new LinkedList<>();
        for (RowBand row : rows) {
            if (row.boxes.size() < minimumColumns) {
                continue;
            }
            for (NativeBox box : row.boxes) {
                edges.add(box.getLeft());
                edges.add(box.getRight());
            }
        }

        if (edges.isEmpty()) {
            for (RowBand row : rows) {
                for (NativeBox box : row.boxes) {
                    edges.add(box.getLeft());
                    edges.add(box.getRight());
                }
            }
        }

        List<Float> clustered = NativeGeometryUtil.clusterPositions(edges, EDGE_TOLERANCE);

        List<Float> boundaries = new ArrayList<>();
        for (Float edge : clustered) {
            if (boundaries.isEmpty() || edge - boundaries.get(boundaries.size() - 1) >= MIN_COLUMN_WIDTH) {
                boundaries.add(edge);
            }
        }
        return boundaries;
    }

    /**
     * A horizontal band of cell boxes.
     */
    private static final class RowBand {
        private float top;
        private float bottom;
        private final List<NativeBox> boxes = new ArrayList<>();

        private RowBand(NativeBox first) {
            this.top = first.getTop();
            this.bottom = first.getBottom();
            this.boxes.add(first);
        }

        private void add(NativeBox box) {
            this.top = Math.min(this.top, box.getTop());
            this.bottom = Math.max(this.bottom, box.getBottom());
            this.boxes.add(box);
        }
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativetable;

import com.finboost.bank.statement.parser.representation.document.extraction.NativeTableLayout;
import com.finboost.bank.statement.parser.representation.document.extraction.Table;
import com.finboost.bank.statement.parser.representation.document.extraction.Word;
import com.finboost.bank.statement.parser.service.document.extraction.post.processor.ColumnTypeIdentifier;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedList;
import java.util.List;
import java.util.Locale;

/**
 * Rebuilds transaction tables for statements that carry no usable table geometry at all.
 *
 * <p>Rows are <em>selected</em> from the text layer: a text line that starts with a transaction date is
 * the beginning of a transaction row, and the wrapped lines that follow it are folded back into that
 * row. Columns come from the vertical whitespace corridors that all selected rows (plus the header
 * line) share, which is what visually aligns such statements in the first place.</p>
 */
@Slf4j
@Service
public class TextAlignedRowSelectedTableExtractor implements NativeTableExtractor {

    private static final String[] HEADER_KEYWORDS = {
            "date", "narration", "description", "particulars", "remarks", "detail",
            "withdrawal", "deposit", "debit", "credit", "amount", "balance",
            "chq", "cheque", "ref", "instrument", "transaction", "value"
    };

    /** Width of one occupancy bucket, in inches. */
    private static final float BUCKET_WIDTH = 0.01f;
    /** Minimum width of a whitespace corridor that separates two columns, in inches. */
    private static final float MIN_CORRIDOR_WIDTH = 0.055f;
    /** Vertical tolerance used to group words into a text line, in inches. */
    private static final float MIN_LINE_TOLERANCE = 0.02f;
    private static final float MIN_COLUMN_WIDTH = 0.10f;
    private static final int MIN_HEADER_KEYWORDS = 2;

    private ColumnTypeIdentifier columnTypeIdentifier;

    @Autowired
    public void setColumnTypeIdentifier(ColumnTypeIdentifier columnTypeIdentifier) {
        this.columnTypeIdentifier = columnTypeIdentifier;
    }

    @Override
    public NativeTableLayout getLayout() {
        return NativeTableLayout.TEXT_ALIGNED_ROW_SELECTED;
    }

    @Override
    public List<Table> extractTables(NativePdfPage page, NativeExtractionPolicy policy) {
        List<Table> tables = new LinkedList<>();
        if (page == null || !page.hasText()) {
            return tables;
        }

        List<TextLineGroup> lines = groupIntoLines(page.getWords());
        if (lines.size() < policy.getMinimumRows()) {
            return tables;
        }

        List<Integer> transactionLines = selectTransactionLines(lines);
        if (transactionLines.size() < Math.max(2, policy.getMinimumRows() - 1)) {
            return tables;
        }

        int headerLine = findHeaderLine(lines, transactionLines.get(0));

        List<TextLineGroup> rowSources = new ArrayList<>();
        if (headerLine >= 0) {
            rowSources.add(lines.get(headerLine));
        }

        // Fold wrapped continuation lines back into the transaction row that owns them.
        List<TextLineGroup> rows = new ArrayList<>(rowSources);
        for (int index = 0; index < transactionLines.size(); index++) {
            int start = transactionLines.get(index);
            int end = index + 1 < transactionLines.size() ? transactionLines.get(index + 1) : lines.size();
            TextLineGroup row = new TextLineGroup(lines.get(start));
            for (int continuation = start + 1; continuation < end; continuation++) {
                row.merge(lines.get(continuation));
            }
            rows.add(row);
        }

        List<Float> columnBoundaries = detectColumnBoundaries(rowSources.isEmpty() ? rows : concat(rowSources, rows));
        if (columnBoundaries.size() < policy.getMinimumColumns() + 1) {
            return tables;
        }

        List<NativeCell> cells = new LinkedList<>();
        for (int rowIndex = 0; rowIndex < rows.size(); rowIndex++) {
            TextLineGroup row = rows.get(rowIndex);
            for (int column = 0; column < columnBoundaries.size() - 1; column++) {
                float left = columnBoundaries.get(column);
                float right = columnBoundaries.get(column + 1);
                List<Word> cellWords = new LinkedList<>();
                for (Word word : row.words) {
                    float centerX = (word.getX1() + word.getX3()) / 2f;
                    boolean lastColumn = column == columnBoundaries.size() - 2;
                    if (centerX >= left && (centerX < right || (lastColumn && centerX <= right))) {
                        cellWords.add(word);
                    }
                }
                cells.add(new NativeCell(rowIndex, column,
                        new NativeBox(left, row.top, right, row.bottom), cellWords));
            }
        }

        Table table = NativeTableAssembler.assemble(page.getPageNumber(), cells, page.getWords(), columnBoundaries);
        if (table != null) {
            tables.add(table);
        }
        return tables;
    }

    private List<TextLineGroup> concat(List<TextLineGroup> first, List<TextLineGroup> second) {
        List<TextLineGroup> all = new ArrayList<>(first);
        all.addAll(second);
        return all;
    }

    private List<TextLineGroup> groupIntoLines(List<Word> words) {
        List<Word> sorted = new ArrayList<>(words);
        sorted.sort(Comparator
                .comparing((Word word) -> word.getY4() == null ? 0f : word.getY4())
                .thenComparing(word -> word.getX1() == null ? 0f : word.getX1()));

        List<TextLineGroup> lines = new LinkedList<>();
        TextLineGroup current = null;

        for (Word word : sorted) {
            float baseline = word.getY4();
            float tolerance = Math.max(MIN_LINE_TOLERANCE,
                    (word.getHeight() == null ? 0f : word.getHeight()) * 0.5f);
            if (current == null || Math.abs(baseline - current.baseline) > tolerance) {
                current = new TextLineGroup(word);
                lines.add(current);
            } else {
                current.add(word);
            }
        }

        for (TextLineGroup line : lines) {
            line.words.sort(Comparator.comparing(word -> word.getX1() == null ? 0f : word.getX1()));
        }

        return lines;
    }

    /**
     * A line starts a transaction row when its leading token - or the leading two tokens, for formats
     * that split "01 Apr 2024" - parses as a date with the very same rules the transaction parser uses.
     */
    private List<Integer> selectTransactionLines(List<TextLineGroup> lines) {
        List<Integer> selected = new LinkedList<>();
        for (int index = 0; index < lines.size(); index++) {
            TextLineGroup line = lines.get(index);
            if (line.words.isEmpty()) {
                continue;
            }
            String first = safeContent(line.words.get(0));
            if (looksLikeDate(first)) {
                selected.add(index);
                continue;
            }
            if (line.words.size() >= 3) {
                String joined = first + safeContent(line.words.get(1)) + safeContent(line.words.get(2));
                if (looksLikeDate(joined)) {
                    selected.add(index);
                }
            }
        }
        return selected;
    }

    private boolean looksLikeDate(String content) {
        if (content == null || content.length() < 5 || content.length() > 12) {
            return false;
        }
        return columnTypeIdentifier != null && columnTypeIdentifier.isDateType(content);
    }

    private int findHeaderLine(List<TextLineGroup> lines, int firstTransactionLine) {
        int bestLine = -1;
        int bestScore = 0;

        for (int index = 0; index < firstTransactionLine; index++) {
            String content = lines.get(index).content().toLowerCase(Locale.ROOT);
            int score = 0;
            for (String keyword : HEADER_KEYWORDS) {
                if (content.contains(keyword)) {
                    score++;
                }
            }
            if (score >= MIN_HEADER_KEYWORDS && score >= bestScore) {
                bestScore = score;
                bestLine = index;
            }
        }

        return bestLine;
    }

    /**
     * Builds the column boundaries out of the vertical whitespace corridors shared by all rows.
     */
    private List<Float> detectColumnBoundaries(List<TextLineGroup> rows) {
        float left = Float.MAX_VALUE;
        float right = -Float.MAX_VALUE;
        for (TextLineGroup row : rows) {
            for (Word word : row.words) {
                left = Math.min(left, word.getX1());
                right = Math.max(right, word.getX3());
            }
        }
        if (left >= right) {
            return new ArrayList<>();
        }

        int bucketCount = (int) Math.ceil((right - left) / BUCKET_WIDTH) + 1;
        boolean[] occupied = new boolean[bucketCount];

        for (TextLineGroup row : rows) {
            for (Word word : row.words) {
                int from = bucketOf(word.getX1(), left, bucketCount);
                int to = bucketOf(word.getX3(), left, bucketCount);
                for (int bucket = from; bucket <= to; bucket++) {
                    occupied[bucket] = true;
                }
            }
        }

        List<Float> boundaries = new ArrayList<>();
        boundaries.add(left);

        int minimumCorridorBuckets = Math.max(2, Math.round(MIN_CORRIDOR_WIDTH / BUCKET_WIDTH));
        int runStart = -1;
        for (int bucket = 0; bucket < bucketCount; bucket++) {
            if (!occupied[bucket]) {
                if (runStart < 0) {
                    runStart = bucket;
                }
                continue;
            }
            if (runStart >= 0) {
                addCorridorBoundary(boundaries, runStart, bucket - 1, minimumCorridorBuckets, left);
                runStart = -1;
            }
        }

        boundaries.add(right);

        // Enforce a sane minimum column width.
        List<Float> filtered = new ArrayList<>();
        for (Float boundary : boundaries) {
            if (filtered.isEmpty() || boundary - filtered.get(filtered.size() - 1) >= MIN_COLUMN_WIDTH) {
                filtered.add(boundary);
            }
        }
        if (filtered.size() >= 2 && filtered.get(filtered.size() - 1) < right) {
            filtered.set(filtered.size() - 1, right);
        }
        return filtered;
    }

    private void addCorridorBoundary(List<Float> boundaries, int runStart, int runEnd, int minimumBuckets, float left) {
        if (runEnd - runStart + 1 < minimumBuckets) {
            return;
        }
        float boundary = left + ((runStart + runEnd) / 2f) * BUCKET_WIDTH;
        boundaries.add(boundary);
    }

    private int bucketOf(float x, float left, int bucketCount) {
        int bucket = Math.round((x - left) / BUCKET_WIDTH);
        if (bucket < 0) {
            return 0;
        }
        return Math.min(bucket, bucketCount - 1);
    }

    private static String safeContent(Word word) {
        String content = word.getContent();
        return content == null ? "" : content.trim();
    }

    /**
     * A visual text line, or a transaction row once its wrapped lines have been merged into it.
     */
    private static final class TextLineGroup {
        private final List<Word> words = new ArrayList<>();
        private float baseline;
        private float top;
        private float bottom;

        private TextLineGroup(Word first) {
            this.baseline = first.getY4();
            this.top = first.getY1();
            this.bottom = first.getY4();
            this.words.add(first);
        }

        private TextLineGroup(TextLineGroup source) {
            this.baseline = source.baseline;
            this.top = source.top;
            this.bottom = source.bottom;
            this.words.addAll(source.words);
        }

        private void add(Word word) {
            this.top = Math.min(this.top, word.getY1());
            this.bottom = Math.max(this.bottom, word.getY4());
            this.words.add(word);
        }

        private void merge(TextLineGroup other) {
            this.top = Math.min(this.top, other.top);
            this.bottom = Math.max(this.bottom, other.bottom);
            this.words.addAll(other.words);
        }

        private String content() {
            StringBuilder builder = new StringBuilder();
            for (Word word : words) {
                if (builder.length() > 0) {
                    builder.append(' ');
                }
                builder.append(safeContent(word));
            }
            return builder.toString();
        }
    }
}

