package com.finboost.bank.statement.parser.service.document.extraction.nativetable;

import com.finboost.bank.statement.parser.representation.document.extraction.Word;
import lombok.extern.slf4j.Slf4j;
import org.apache.pdfbox.Loader;
import org.apache.pdfbox.pdmodel.PDDocument;
import org.apache.pdfbox.pdmodel.PDPage;
import org.apache.pdfbox.pdmodel.common.PDRectangle;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import java.io.File;
import java.util.Comparator;
import java.util.LinkedList;
import java.util.List;

/**
 * Reads the native content - text layer plus vector geometry - of every page of an electronic PDF.
 *
 * <p>The reader deliberately refuses documents that the native path cannot handle faithfully (rotated
 * pages, or pages without any text layer, i.e. scanned statements). Those documents are then processed
 * by the remote ML extraction, exactly as before.</p>
 */
@Slf4j
@Service
public class NativePdfPageReader {

    private static final float POINTS_PER_INCH = 72.0f;

    private NativeWordExtractor nativeWordExtractor;

    @Autowired
    public void setNativeWordExtractor(NativeWordExtractor nativeWordExtractor) {
        this.nativeWordExtractor = nativeWordExtractor;
    }

    /**
     * @param file the statement PDF
     * @return the native content of every page, or an empty list when the document cannot be handled
     * natively
     */
    public List<NativePdfPage> readPages(File file) {
        List<NativePdfPage> pages = new LinkedList<>();
        if (file == null || !file.isFile()) {
            return pages;
        }

        try (PDDocument document = Loader.loadPDF(file)) {
            int pageCount = document.getNumberOfPages();
            for (int pageIndex = 0; pageIndex < pageCount; pageIndex++) {
                PDPage pdPage = document.getPage(pageIndex);

                int rotation = ((pdPage.getRotation() % 360) + 360) % 360;
                if (rotation != 0) {
                    log.info("Skipping native transaction table extraction, page {} is rotated by {} degrees",
                            pageIndex + 1, rotation);
                    return new LinkedList<>();
                }

                NativePdfPage page = readPage(document, pdPage, pageIndex + 1);
                if (!page.hasText()) {
                    log.info("Skipping native transaction table extraction, page {} has no text layer",
                            pageIndex + 1);
                    return new LinkedList<>();
                }
                pages.add(page);
            }
        } catch (Exception e) {
            log.warn("Native PDF page reading failed, falling back to ML extraction: {}", e.getMessage());
            return new LinkedList<>();
        }

        return pages;
    }

    private NativePdfPage readPage(PDDocument document, PDPage pdPage, int pageNumber) throws Exception {
        PDRectangle cropBox = pdPage.getCropBox();

        NativePdfPage page = new NativePdfPage();
        page.setPageNumber(pageNumber);
        page.setWidth(cropBox.getWidth() / POINTS_PER_INCH);
        page.setHeight(cropBox.getHeight() / POINTS_PER_INCH);

        List<Word> words = nativeWordExtractor.extractWords(document, pageNumber);
        page.setWords(words);
        page.setTextContent(buildPageText(words));

        PdfVectorGeometryCollector collector = new PdfVectorGeometryCollector(pdPage);
        try {
            collector.processPage(pdPage);
            page.setHorizontalRulings(collector.getHorizontalRulings());
            page.setVerticalRulings(collector.getVerticalRulings());
            page.setBoxes(collector.getBoxes());
        } catch (Exception e) {
            log.debug("Could not collect vector geometry of page {}: {}", pageNumber, e.getMessage());
        }

        return page;
    }

    /**
     * Rebuilds the plain text of the page from its words so that the basic detail extraction keeps
     * working on natively extracted documents.
     */
    private String buildPageText(List<Word> words) {
        if (words == null || words.isEmpty()) {
            return "";
        }

        List<Word> sorted = new LinkedList<>(words);
        sorted.sort(Comparator
                .comparing((Word word) -> word.getY4() == null ? 0f : word.getY4())
                .thenComparing(word -> word.getX1() == null ? 0f : word.getX1()));

        StringBuilder builder = new StringBuilder();
        Float lineBaseline = null;
        for (Word word : sorted) {
            float baseline = word.getY4() == null ? 0f : word.getY4();
            float tolerance = Math.max(0.02f, (word.getHeight() == null ? 0f : word.getHeight()) * 0.5f);
            if (lineBaseline == null) {
                lineBaseline = baseline;
            } else if (Math.abs(baseline - lineBaseline) > tolerance) {
                builder.append('\n');
                lineBaseline = baseline;
            } else {
                builder.append(' ');
            }
            builder.append(word.getContent() == null ? "" : word.getContent());
        }

        return builder.toString();
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativetable;

import com.finboost.bank.statement.parser.representation.document.extraction.DocumentExtractionResult;
import com.finboost.bank.statement.parser.representation.document.extraction.NativeTableLayout;
import lombok.AllArgsConstructor;
import lombok.Data;

import java.util.Collections;
import java.util.List;

/**
 * The outcome of the native transaction table extraction for one statement.
 */
@Data
public class NativeExtractionAttempt {

    /** {@code true} when the bank-format family is one of the natively supported ones. */
    private final boolean supported;

    /** The policy that was applied, {@code null} when the family is not supported. */
    private final NativeExtractionPolicy policy;

    /**
     * One candidate per native layout that produced at least one table, in policy priority order.
     */
    private final List<Candidate> candidates;

    private NativeExtractionAttempt(boolean supported, NativeExtractionPolicy policy, List<Candidate> candidates) {
        this.supported = supported;
        this.policy = policy;
        this.candidates = candidates == null ? Collections.emptyList() : candidates;
    }

    public static NativeExtractionAttempt unsupported() {
        return new NativeExtractionAttempt(false, null, Collections.emptyList());
    }

    public static NativeExtractionAttempt of(NativeExtractionPolicy policy, List<Candidate> candidates) {
        return new NativeExtractionAttempt(true, policy, candidates);
    }

    public boolean hasCandidates() {
        return !candidates.isEmpty();
    }

    /**
     * A natively reconstructed document, still to be validated by the shared document analysis.
     */
    @Data
    @AllArgsConstructor
    public static class Candidate {
        private final NativeTableLayout layout;
        private final DocumentExtractionResult result;
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativetable;

import com.finboost.bank.statement.parser.representation.document.extraction.DocumentExtractionRequest;
import com.finboost.bank.statement.parser.representation.document.extraction.DocumentExtractionResult;
import com.finboost.bank.statement.parser.representation.document.extraction.NativeTableLayout;
import com.finboost.bank.statement.parser.representation.document.extraction.Page;
import com.finboost.bank.statement.parser.representation.document.extraction.Table;
import com.finboost.bank.statement.parser.representation.document.extraction.TransactionExtractionMode;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import java.util.ArrayList;
import java.util.EnumMap;
import java.util.LinkedHashMap;
import java.util.LinkedList;
import java.util.List;
import java.util.Map;

/**
 * Offline (native) transaction table extraction.
 *
 * <p>For the bank-format families registered in {@link NativeExtractionPolicyRegistry} the transaction
 * tables are reconstructed directly from the PDF content stream. The service produces one candidate
 * document per native layout declared by the policy; the caller then validates the candidates with the
 * shared document analysis and only invokes the remote ML extraction when none of them works.</p>
 */
@Slf4j
@Service
public class NativeTransactionTableExtractionService {

    private NativeExtractionPolicyRegistry policyRegistry;
    private NativePdfPageReader pageReader;
    private final Map<NativeTableLayout, NativeTableExtractor> extractors = new EnumMap<>(NativeTableLayout.class);

    @Autowired
    public void setPolicyRegistry(NativeExtractionPolicyRegistry policyRegistry) {
        this.policyRegistry = policyRegistry;
    }

    @Autowired
    public void setPageReader(NativePdfPageReader pageReader) {
        this.pageReader = pageReader;
    }

    @Autowired
    public void setTableExtractors(List<NativeTableExtractor> tableExtractors) {
        this.extractors.clear();
        if (tableExtractors != null) {
            for (NativeTableExtractor extractor : tableExtractors) {
                this.extractors.put(extractor.getLayout(), extractor);
            }
        }
    }

    /**
     * @return whether the bank of the request belongs to a natively supported bank-format family
     */
    public boolean isNativelySupported(String bankCode) {
        return policyRegistry.isSupported(bankCode);
    }

    /**
     * Attempts the native extraction for the given statement.
     *
     * @return the attempt, {@link NativeExtractionAttempt#unsupported()} when the bank-format family is
     * not supported natively
     */
    public NativeExtractionAttempt extract(DocumentExtractionRequest request) {
        if (request == null || request.getStatementFile() == null) {
            return NativeExtractionAttempt.unsupported();
        }

        NativeExtractionPolicy policy = policyRegistry.findPolicy(request.getBankName());
        if (policy == null) {
            return NativeExtractionAttempt.unsupported();
        }

        List<NativePdfPage> pages = pageReader.readPages(request.getStatementFile());
        if (pages.isEmpty()) {
            log.info("Native transaction table extraction not applicable for bank {}, no native page content",
                    policy.getBankCode());
            return NativeExtractionAttempt.of(policy, new LinkedList<>());
        }

        List<NativeExtractionAttempt.Candidate> candidates = new LinkedList<>();
        for (NativeTableLayout layout : policy.getCandidateLayouts()) {
            NativeTableExtractor extractor = extractors.get(layout);
            if (extractor == null) {
                log.warn("No native table extractor registered for layout {}", layout);
                continue;
            }

            DocumentExtractionResult result = buildResult(pages, extractor, policy);
            if (result != null) {
                candidates.add(new NativeExtractionAttempt.Candidate(layout, result));
            }
        }

        log.info("Native transaction table extraction produced {} candidate layout(s) for bank {}",
                candidates.size(), policy.getBankCode());

        return NativeExtractionAttempt.of(policy, candidates);
    }

    /**
     * Runs one extractor over every page and maps the outcome onto a
     * {@link DocumentExtractionResult} that is structurally identical to a remote ML result.
     */
    private DocumentExtractionResult buildResult(List<NativePdfPage> nativePages,
                                                 NativeTableExtractor extractor,
                                                 NativeExtractionPolicy policy) {
        Map<Integer, Page> pages = new LinkedHashMap<>();
        int tableCount = 0;

        for (NativePdfPage source : nativePages) {
            NativePdfPage nativePage = source.copyForExtraction();

            List<Table> tables;
            try {
                tables = extractor.extractTables(nativePage, policy);
            } catch (Exception e) {
                log.warn("Native {} extraction failed on page {}: {}",
                        extractor.getLayout(), nativePage.getPageNumber(), e.getMessage());
                return null;
            }

            Map<Integer, Table> tableMap = new LinkedHashMap<>();
            int tableIndex = 0;
            for (Table table : tables) {
                tableMap.put(tableIndex++, table);
            }
            tableCount += tableMap.size();

            Page page = new Page();
            page.setPageNumber(nativePage.getPageNumber());
            page.setWidth((double) nativePage.getWidth());
            page.setHeight((double) nativePage.getHeight());
            page.setWords(new ArrayList<>(nativePage.getWords()));
            page.setContent(nativePage.getTextContent());
            page.setTables(tableMap);

            pages.put(page.getPageNumber(), page);
        }

        if (tableCount == 0) {
            return null;
        }

        DocumentExtractionResult result = new DocumentExtractionResult();
        result.setPages(pages);
        result.setNoOfPages(pages.size());
        result.setTransactionExtractionMode(TransactionExtractionMode.NATIVE);
        result.setNativeTableLayout(extractor.getLayout());

        return result;
    }
}

package com.finboost.bank.statement.parser.service.document.extraction;

import com.finboost.bank.statement.parser.representation.document.extraction.DocumentExtractionRequest;
import com.finboost.bank.statement.parser.representation.document.extraction.DocumentExtractionResult;
import com.finboost.bank.statement.parser.service.document.extraction.post.processor.AnalyzeDocuments;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

/**
 * The document analysis that every extracted document goes through, regardless of whether its tables
 * were produced natively or by the remote ML layout model.
 *
 * <p>Keeping this in one place is what allows a natively extracted document to be carried through the
 * exact same normalisation, column typing and row transformation steps as an ML extracted one.</p>
 */
@Slf4j
@Service
public class DocumentAnalysisPipeline {

    private static final int VERIFICATION_PAGE_LIMIT = 5;

    private AnalyzeDocuments analyzeDocuments;
    private IBankSpecificParsingService bankSpecificParsingService;

    @Autowired
    public void setAnalyzeDocuments(AnalyzeDocuments analyzeDocuments) {
        this.analyzeDocuments = analyzeDocuments;
    }

    @Autowired
    public void setBankSpecificParsingService(IBankSpecificParsingService bankSpecificParsingService) {
        this.bankSpecificParsingService = bankSpecificParsingService;
    }

    /**
     * Runs the shared post extraction analysis on the given result.
     *
     * @param result    the extracted document, modified in place
     * @param request   the originating request, used for the bank specific rules
     * @param pageCount the number of pages of the document
     * @return the very same result instance
     */
    public DocumentExtractionResult analyze(DocumentExtractionResult result,
                                            DocumentExtractionRequest request,
                                            int pageCount) {
        if (result == null) {
            return null;
        }

        // check if the bank statement parsing happens bank specific
        bankSpecificParsingService.identifyBankSpecificStatementProcess(result, request);

        if (result.isSkipFurtherProcessing()) {
            return result;
        }

        DocumentExtractionResult preProcessedResultByHeader =
                analyzeDocuments.preProcessForVerificationByHeader(result, VERIFICATION_PAGE_LIMIT);
        if (preProcessedResultByHeader != null && preProcessedResultByHeader.getPreProcessVerificationResult() != null) {
            result.setPreProcessVerificationResult(preProcessedResultByHeader.getPreProcessVerificationResult());
        } else {
            DocumentExtractionResult preprocessedResult = analyzeDocuments.preProcessForVerification(result, pageCount);
            if (preprocessedResult != null && preprocessedResult.getPreProcessVerificationResult() != null) {
                result.setPreProcessVerificationResult(preprocessedResult.getPreProcessVerificationResult());
            }
        }

        analyzeDocuments.analyzeDocument(result, true, true, true);

        return result;
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativetable;

import com.finboost.bank.statement.parser.representation.bankAccount.BankTransactionVO;
import com.finboost.bank.statement.parser.representation.bankstatement.BankStatementVO;
import com.finboost.bank.statement.parser.representation.document.extraction.DocumentExtractionResult;
import com.finboost.bank.statement.parser.representation.document.extraction.Page;
import com.finboost.bank.statement.parser.representation.document.extraction.Table;
import com.finboost.bank.statement.parser.service.bankstatement.InconsistencyFinderService;
import com.finboost.bank.statement.parser.service.document.extraction.bankstatement.BankStatementProcessorImpl;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;

import java.util.LinkedList;
import java.util.List;

/**
 * Decides whether a natively reconstructed document is good enough to be used instead of the remote ML
 * extraction.
 *
 * <p>Acceptance is deliberately based on the production transaction extraction itself: the candidate is
 * only accepted when the existing extractor finds a sufficient number of transactions <em>and</em> their
 * running balances are consistent (in statement order or in reverse order). A wrongly reconstructed grid
 * practically never satisfies the balance chain, which makes this a strong and cheap validation.</p>
 */
@Slf4j
@Service
public class NativeExtractionValidator {

    private static final int MINIMUM_TRANSACTIONS = 2;

    /**
     * @param result an already analysed native extraction candidate
     * @return {@code true} when the candidate can be used as the final extraction result
     */
    public boolean isUsable(DocumentExtractionResult result) {
        if (result == null || result.getPages() == null || result.getPages().isEmpty()) {
            return false;
        }

        if (!hasTransactionTable(result)) {
            return false;
        }

        if (result.isSkipFurtherProcessing()) {
            // A bank specific processor has taken ownership of the tables, trust its outcome.
            return true;
        }

        List<BankTransactionVO> transactions = extractTransactions(result);
        if (transactions == null || transactions.size() < MINIMUM_TRANSACTIONS) {
            log.debug("Native candidate rejected, only {} transaction(s) found",
                    transactions == null ? 0 : transactions.size());
            return false;
        }

        if (result.isStatementWithoutBalance()) {
            // Balances were synthesised, the chain check would be meaningless.
            return true;
        }

        if (isBalanceChainConsistent(transactions)) {
            return true;
        }

        List<BankTransactionVO> reversed = new LinkedList<>();
        for (int index = transactions.size() - 1; index >= 0; index--) {
            reversed.add(transactions.get(index));
        }
        if (isBalanceChainConsistent(reversed)) {
            return true;
        }

        log.debug("Native candidate rejected, balance chain of {} transaction(s) is inconsistent",
                transactions.size());
        return false;
    }

    private boolean hasTransactionTable(DocumentExtractionResult result) {
        for (Page page : result.getPages().values()) {
            if (page.getTables() == null) {
                continue;
            }
            for (Table table : page.getTables().values()) {
                if (table != null && table.getIsTransactionTable()) {
                    return true;
                }
            }
        }
        return false;
    }

    private List<BankTransactionVO> extractTransactions(DocumentExtractionResult result) {
        try {
            BankStatementVO bankStatementVO = new BankStatementVO();
            bankStatementVO.setDocumentExtractionResult(result);

            List<BankStatementVO> statements = new LinkedList<>();
            statements.add(bankStatementVO);

            BankStatementProcessorImpl.extractTransactions(statements, false);

            return statements.get(0).getBankTransactions();
        } catch (Exception e) {
            log.debug("Native candidate validation failed while extracting transactions: {}", e.getMessage());
            return null;
        }
    }

    private boolean isBalanceChainConsistent(List<BankTransactionVO> transactions) {
        Integer inconsistencyCount = InconsistencyFinderService.checkInconsistencyForCount(transactions);
        return inconsistencyCount != null && inconsistencyCount == 0;
    }
}

