import com.finboost.bank.statement.parser.service.document.extraction.DocumentExtractionService;
import com.finboost.bank.statement.parser.service.document.extraction.bankstatement.BankStatementProcessorImpl;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.NativeExtractionAttempt;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.NativeExtractionValidator;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.NativeTransactionTableExtractionService;
import com.finboost.bank.statement.parser.service.document.extraction.post.processor.EPdfCharacterExtractionService;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import java.io.IOException;

/**
 * Document extraction entry point.
 *
 * <p>The offline native transaction table extraction is attempted first for the bank-format families
 * that support it; when one of its layouts yields a usable transaction table the result is carried
 * through the shared document analysis and the remote ML model is never called. Unknown or unsupported
 * layouts - and supported layouts that could not be reconstructed - keep using Azure Document
 * Intelligence exactly as before.</p>
 */
@Service
@Slf4j
public class AzureDocumentExtractionServiceImpl implements DocumentExtractionService {

    private AzureDocumentIntelligenceProcessor azureDocumentIntelligenceProcessor;
    private AzureDocumentIntelligenceResponseMapper azureDocumentIntelligenceResponseMapper;
    private EPdfCharacterExtractionService ePdfCharacterExtractionService;
    private DocumentAnalysisPipeline documentAnalysisPipeline;
    private NativeTransactionTableExtractionService nativeTransactionTableExtractionService;
    private NativeExtractionValidator nativeExtractionValidator;

    @Autowired
    public void setAzureDocumentIntelligenceProcessor(AzureDocumentIntelligenceProcessor azureDocumentIntelligenceProcessor) {
        this.azureDocumentIntelligenceProcessor = azureDocumentIntelligenceProcessor;
    }

    @Autowired
    public void setAzureDocumentIntelligenceResponseMapper(AzureDocumentIntelligenceResponseMapper azureDocumentIntelligenceResponseMapper) {
        this.azureDocumentIntelligenceResponseMapper = azureDocumentIntelligenceResponseMapper;
    }

    @Autowired
    public void setEPdfCharacterExtractionService(EPdfCharacterExtractionService ePdfCharacterExtractionService) {
        this.ePdfCharacterExtractionService = ePdfCharacterExtractionService;
    }

    @Autowired
    public void setDocumentAnalysisPipeline(DocumentAnalysisPipeline documentAnalysisPipeline) {
        this.documentAnalysisPipeline = documentAnalysisPipeline;
    }

    @Autowired
    public void setNativeTransactionTableExtractionService(NativeTransactionTableExtractionService nativeTransactionTableExtractionService) {
        this.nativeTransactionTableExtractionService = nativeTransactionTableExtractionService;
    }

    @Autowired
    public void setNativeExtractionValidator(NativeExtractionValidator nativeExtractionValidator) {
        this.nativeExtractionValidator = nativeExtractionValidator;
    }

    @Override
    public DocumentExtractionResult extractDocument(BankStatementVO bankStatementVO) throws IOException {
        DocumentExtractionRequest documentExtractionRequest = new DocumentExtractionRequest();
        documentExtractionRequest.setStatementFile(bankStatementVO.getDecryptedFile());
        documentExtractionRequest.setBankName(bankStatementVO.getBank());
        try{
            documentExtractionRequest.setStatementFromDate(BankStatementProcessorImpl.parseDate(bankStatementVO.getBankAccountDetailsVO().getStatementFrom()));
        }catch (Exception e){
            log.warn("Failed to parse statement-from-date from date string {}", bankStatementVO.getBankAccountDetailsVO().getStatementFrom());
        }
        return extractDocument(documentExtractionRequest);
    }

    @Override
    public DocumentExtractionResult extractDocument(DocumentExtractionRequest request) throws IOException {
        NativeExtractionAttempt nativeAttempt = attemptNativeExtraction(request);

        DocumentExtractionResult nativeResult = selectNativeResult(nativeAttempt, request);
        if (nativeResult != null) {
            return nativeResult;
        }

        return extractWithMachineLearning(request, nativeAttempt);
    }

    private NativeExtractionAttempt attemptNativeExtraction(DocumentExtractionRequest request) {
        try {
            return nativeTransactionTableExtractionService.extract(request);
        } catch (Exception e) {
            log.warn("Native transaction table extraction failed, falling back to ML extraction: {}", e.getMessage());
            return NativeExtractionAttempt.unsupported();
        }
    }

    /**
     * Analyses every native candidate with the shared pipeline and returns the first usable one.
     */
    private DocumentExtractionResult selectNativeResult(NativeExtractionAttempt nativeAttempt,
                                                        DocumentExtractionRequest request) {
        for (NativeExtractionAttempt.Candidate candidate : nativeAttempt.getCandidates()) {
            DocumentExtractionResult result = candidate.getResult();
            try {
                documentAnalysisPipeline.analyze(result, request, result.getNoOfPages() == null ? 0 : result.getNoOfPages());
            } catch (Exception e) {
                log.warn("Native {} candidate could not be analysed: {}", candidate.getLayout(), e.getMessage());
                continue;
            }

            if (nativeExtractionValidator.isUsable(result)) {
                result.setTransactionExtractionMode(TransactionExtractionMode.NATIVE);
                result.setNativeTableLayout(candidate.getLayout());
                log.info("Transaction tables extracted natively using the {} layout for bank {}",
                        candidate.getLayout(), request.getBankName());
                return result;
            }

            log.info("Native {} candidate rejected for bank {}", candidate.getLayout(), request.getBankName());
        }

        return null;
    }

    private DocumentExtractionResult extractWithMachineLearning(DocumentExtractionRequest request,
                                                                NativeExtractionAttempt nativeAttempt) throws IOException {
        TransactionExtractionMode mode = nativeAttempt.isSupported()
                ? TransactionExtractionMode.NATIVE_FALLBACK_ML
                : TransactionExtractionMode.ML;

        if (nativeAttempt.isSupported()) {
            log.info("Falling back to ML extraction for bank {}, no native layout produced a usable table",
                    request.getBankName());
        }

        // Process with Azure Document Intelligence
        AnalyzeResult analyzeResult = azureDocumentIntelligenceProcessor.processDocument(request.getStatementFile());
        DocumentExtractionResult result = azureDocumentIntelligenceResponseMapper.mapAnalyzeResultToDocument(analyzeResult);
        result.setTransactionExtractionMode(mode);

        // Enhance with character-level information right after mapping
        try {
            boolean enhanced = ePdfCharacterExtractionService.enhanceDocumentWithCharacterInfo(result, request.getStatementFile());
            if (enhanced) {
                log.info("Successfully enhanced document with character-level information");
            } else {
                log.info("Document could not be enhanced with character-level information (likely a scanned PDF)");
            }
        } catch (Exception e) {
            log.warn("Failed to enhance document with character-level information: {}", e.getMessage());
        }

        return documentAnalysisPipeline.analyze(result, request, analyzeResult.getPages().size());
    }
}

