import com.finboost.bank.statement.parser.representation.bankAccount.BankTransactionVO;
import com.finboost.bank.statement.parser.representation.bankstatement.BankStatementVO;
import com.finboost.bank.statement.parser.representation.document.extraction.*;
import com.finboost.bank.statement.parser.service.document.extraction.bankstatement.BankStatementProcessorImpl;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.*;
import com.finboost.bank.statement.parser.service.document.extraction.post.processor.*;

import java.io.File;
import java.util.*;

public class NativeHarness {

    static ColumnTypeIdentifier columnTypeIdentifier = new ColumnTypeIdentifier();
    static BankTransactionColumnTypeIdentifier txnColTypeIdentifier = new BankTransactionColumnTypeIdentifier();
    static BankTransactionTableIdentifier tableIdentifier = new BankTransactionTableIdentifier();
    static TableColumnNormalizer columnNormalizer = new TableColumnNormalizer();
    static TableRowNormalizer rowNormalizer = new TableRowNormalizer();
    static BankTransactionRowNormalizer txnRowNormalizer = new BankTransactionRowNormalizer();
    static BankTransactionTableHeaderIdentifier headerIdentifier = new BankTransactionTableHeaderIdentifier();
    static BankTransactionTableFooterIdentifier footerIdentifier = new BankTransactionTableFooterIdentifier();

    static void analyze(DocumentExtractionResult result) {
        columnNormalizer.normalizeTableColumn(result);
        rowNormalizer.normalizeTableRows(result);
        columnTypeIdentifier.identifyColumnTypes(result);
        headerIdentifier.identifyAndMarkHeaderCells(result);
        footerIdentifier.IdentifyAndMarkFooterCells(result);
        txnColTypeIdentifier.identifyColumnTransactionTypeByHeader(result);
        txnColTypeIdentifier.assignColumnTransactionTypes(result);
        tableIdentifier.identifyBankTransactionTables(result);
        txnColTypeIdentifier.reassignColumnTransactionTypesIfReverseOrder(result);
        txnRowNormalizer.transformTables(result);
    }

    public static void main(String[] args) throws Exception {
        NativeWordExtractor wordExtractor = new NativeWordExtractor();
        NativePdfPageReader reader = new NativePdfPageReader();
        reader.setNativeWordExtractor(wordExtractor);
        NativeExtractionPolicyRegistry registry = new NativeExtractionPolicyRegistry();
        TextAlignedRowSelectedTableExtractor textAligned = new TextAlignedRowSelectedTableExtractor();
        textAligned.setColumnTypeIdentifier(columnTypeIdentifier);
        Map<NativeTableLayout, NativeTableExtractor> extractors = new EnumMap<>(NativeTableLayout.class);
        for (NativeTableExtractor e : List.of(new BorderedGridTableExtractor(), new BoxGuidedTableExtractor(), textAligned)) {
            extractors.put(e.getLayout(), e);
        }
        NativeExtractionValidator validator = new NativeExtractionValidator();

        int ok = 0, fail = 0;
        for (String path : args) {
            File f = new File(path);
            String bank = f.getParentFile().getName();
            NativeExtractionPolicy policy = registry.findPolicy(bank);
            if (policy == null) { System.out.printf("%-60s UNSUPPORTED%n", short_(path)); continue; }
            List<NativePdfPage> pages = reader.readPages(f);
            if (pages.isEmpty()) { System.out.printf("%-60s NO-NATIVE-CONTENT%n", short_(path)); fail++; continue; }

            String verdict = "REJECTED";
            for (NativeTableLayout layout : policy.getCandidateLayouts()) {
                NativeTableExtractor extractor = extractors.get(layout);
                DocumentExtractionResult result = new DocumentExtractionResult();
                Map<Integer, Page> pmap = new LinkedHashMap<>();
                int tables = 0;
                for (NativePdfPage src : pages) {
                    NativePdfPage np = src.copyForExtraction();
                    List<Table> ts;
                    try { ts = extractor.extractTables(np, policy); } catch (Exception ex) { ts = List.of(); }
                    Map<Integer, Table> tm = new LinkedHashMap<>();
                    int i = 0;
                    for (Table t : ts) tm.put(i++, t);
                    tables += tm.size();
                    Page p = new Page();
                    p.setPageNumber(np.getPageNumber());
                    p.setWidth((double) np.getWidth());
                    p.setHeight((double) np.getHeight());
                    p.setWords(new ArrayList<>(np.getWords()));
                    p.setContent(np.getTextContent());
                    p.setTables(tm);
                    pmap.put(p.getPageNumber(), p);
                }
                if (tables == 0) continue;
                result.setPages(pmap);
                result.setNoOfPages(pmap.size());
                try { analyze(result); } catch (Exception ex) { continue; }
                int txnCount = countTxns(result);
                if (validator.isUsable(result)) { verdict = "OK " + layout + " txns=" + txnCount; break; }
                verdict = "REJECTED(last=" + layout + " txns=" + txnCount + ")";
            }
            if (verdict.startsWith("OK")) ok++; else fail++;
            System.out.printf("%-60s %s%n", short_(path), verdict);
        }
        System.out.println("=== native accepted=" + ok + " fallback=" + fail);
    }

    static int countTxns(DocumentExtractionResult r) {
        try {
            BankStatementVO vo = new BankStatementVO();
            vo.setDocumentExtractionResult(r);
            List<BankStatementVO> l = new LinkedList<>(); l.add(vo);
            BankStatementProcessorImpl.extractTransactions(l, false);
            List<BankTransactionVO> t = l.get(0).getBankTransactions();
            return t == null ? 0 : t.size();
        } catch (Exception e) { return -1; }
    }

    static String short_(String p) { return p.replace("/app/src/test/resources/pdf-samples-latest/", ""); }
}
