import com.finboost.bank.statement.parser.representation.document.extraction.*;
import com.finboost.bank.statement.parser.service.document.extraction.nativetable.*;
import com.finboost.bank.statement.parser.service.document.extraction.post.processor.ColumnTypeIdentifier;
import java.io.File;
import java.util.*;

public class Dbg2 {
    public static void main(String[] a) throws Exception {
        NativeWordExtractor we = new NativeWordExtractor();
        NativePdfPageReader reader = new NativePdfPageReader();
        reader.setNativeWordExtractor(we);
        List<NativePdfPage> pages = reader.readPages(new File(a[0]));
        int pi = a.length > 1 ? Integer.parseInt(a[1]) : 0;
        NativePdfPage p = pages.get(pi);
        ColumnTypeIdentifier cti = new ColumnTypeIdentifier();
        // group lines
        List<Word> sorted = new ArrayList<>(p.getWords());
        sorted.sort(Comparator.comparing((Word w) -> w.getY4()).thenComparing(Word::getX1));
        List<List<Word>> lines = new ArrayList<>();
        List<Word> cur = null; float base = 0;
        for (Word w : sorted) {
            float tol = Math.max(0.02f, w.getHeight()*0.5f);
            if (cur == null || Math.abs(w.getY4()-base) > tol) { cur = new ArrayList<>(); lines.add(cur); base = w.getY4(); }
            cur.add(w);
        }
        int dates = 0;
        for (List<Word> line : lines) {
            String first = line.get(0).getContent().trim();
            boolean d = first.length()>=5 && first.length()<=12 && cti.isDateType(first);
            String joined = line.size()>=3 ? (first + line.get(1).getContent().trim() + line.get(2).getContent().trim()) : "";
            boolean d2 = joined.length()>=5 && joined.length()<=12 && cti.isDateType(joined);
            if (d || d2) dates++;
            System.out.printf("%s%s [%s] :: %s%n", d?"D":" ", d2?"J":" ", first, join(line));
        }
        System.out.println("lines=" + lines.size() + " dateLines=" + dates);
    }
    static String join(List<Word> l) { StringBuilder b = new StringBuilder(); for (Word w : l) { b.append(w.getContent()).append(' '); } String s = b.toString(); return s.length()>150 ? s.substring(0,150) : s; }
}
