    /**
     * Median of the given values, {@code fallback} when the list is empty.
     */
    public static float median(List<Float> values, float fallback) {
        if (values == null || values.isEmpty()) {
            return fallback;
        }
        List<Float> sorted = new ArrayList<>(values);
        Collections.sort(sorted);
        return sorted.get(sorted.size() / 2);
    }

    /**
     * Like {@link #clusterPositions(List, float)} but only keeps the clusters that gathered at least
     * {@code minimumSupport} values. Used to turn the many short strokes of a table border into the few
     * coordinates that are actually shared by several cells.
     */
    public static List<Float> clusterPositions(List<Float> positions, float tolerance, int minimumSupport) {
        List<Float> clustered = new LinkedList<>();
        if (positions == null || positions.isEmpty()) {
            return clustered;
        }

        List<Float> sorted = new ArrayList<>(positions);
        Collections.sort(sorted);

        float sum = sorted.get(0);
        int count = 1;
        float reference = sorted.get(0);

        for (int i = 1; i < sorted.size(); i++) {
            float value = sorted.get(i);
            if (value - reference <= tolerance) {
                sum += value;
                count++;
            } else {
                if (count >= minimumSupport) {
                    clustered.add(sum / count);
                }
                sum = value;
                count = 1;
                reference = value;
            }
        }
        if (count >= minimumSupport) {
            clustered.add(sum / count);
        }

        return clustered;
    }

    /**
     * Drops boundaries that would create bands narrower than {@code minimumWidth}, always keeping the
     * first one.
     */
    public static List<Float> enforceMinimumBandWidth(List<Float> boundaries, float minimumWidth) {
        List<Float> filtered = new ArrayList<>();
        if (boundaries == null) {
            return filtered;
        }
        for (Float boundary : boundaries) {
            if (filtered.isEmpty() || boundary - filtered.get(filtered.size() - 1) >= minimumWidth) {
                filtered.add(boundary);
            }
        }
        return filtered;
    }
}

