package com.finboost.bank.statement.parser.service.document.extraction.nativetable;

import com.finboost.bank.statement.parser.representation.document.extraction.NativeTableLayout;
import com.finboost.bank.statement.parser.representation.document.extraction.Table;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;

import java.util.ArrayList;
import java.util.LinkedList;
import java.util.List;

/**
 * Rebuilds transaction tables from the ruling grid drawn by the statement.
 *
 * <p>Banks draw that grid in very different ways: as long strokes, as hair-thin filled rectangles, as
 * one short stroke per cell edge, and quite often only along one axis. The extractor therefore derives
 * each axis from the strongest available evidence:</p>
 *
 * <ol>
 *     <li>row boundaries come from the horizontal lines that span most of the table width, and - when
 *     the statement does not rule its rows at all - from the endpoints shared by the vertical strokes of
 *     each row,</li>
 *     <li>column boundaries come from the vertical lines that span a significant part of the table
 *     height, and - when the statement does not rule its columns - from the endpoints shared by the
 *     horizontal strokes of each row,</li>
 *     <li>the resulting (row band x column band) grid is materialised into cells and the page words are
 *     attributed to them.</li>
 * </ol>
 */
@Slf4j
@Service
public class BorderedGridTableExtractor implements NativeTableExtractor {

    private static final float POSITION_TOLERANCE = 0.022f;
    private static final float SEGMENT_GAP_TOLERANCE = 0.06f;
    /** A horizontal line must cover this fraction of the widest one to act as a row boundary. */
    private static final float ROW_LINE_COVERAGE = 0.55f;
    /** A vertical line must cover this fraction of the table height to act as a column boundary. */
    private static final float COLUMN_LINE_COVERAGE = 0.25f;
    /** How many strokes must share a coordinate before it is accepted as an inferred boundary. */
    private static final int INFERRED_BOUNDARY_SUPPORT = 2;
    private static final float MIN_ROW_HEIGHT = 0.045f;
    private static final float MIN_COLUMN_WIDTH = 0.10f;

    @Override
    public NativeTableLayout getLayout() {
        return NativeTableLayout.BORDERED_GRID;
    }

    @Override
    public List<Table> extractTables(NativePdfPage page, NativeExtractionPolicy policy) {
        List<Table> tables = new LinkedList<>();
        if (page == null || !page.hasText()) {
            return tables;
        }

        List<NativeRuling> horizontal = NativeGeometryUtil.mergeCollinear(
                page.getHorizontalRulings(), POSITION_TOLERANCE, SEGMENT_GAP_TOLERANCE);
        List<NativeRuling> vertical = NativeGeometryUtil.mergeCollinear(
                page.getVerticalRulings(), POSITION_TOLERANCE, SEGMENT_GAP_TOLERANCE);

        if (horizontal.isEmpty() && vertical.isEmpty()) {
            return tables;
        }

        List<Float> rowBoundaries = rowBoundaries(page, horizontal, policy);
        if (rowBoundaries.size() < policy.getMinimumRows() + 1) {
            return tables;
        }

        for (List<Float> group : splitIntoGrids(rowBoundaries, policy.getMaximumRowGap())) {
            if (group.size() < policy.getMinimumRows() + 1) {
                continue;
            }
            Table table = buildTable(page, group, vertical, policy);
            if (table != null) {
                tables.add(table);
            }
        }

        return tables;
    }

    /**
     * Row boundaries, preferring real horizontal rulings and falling back to the row separations that
     * the vertical strokes imply.
     */
    private List<Float> rowBoundaries(NativePdfPage page,
                                      List<NativeRuling> mergedHorizontal,
                                      NativeExtractionPolicy policy) {
        float widestLine = 0f;
        for (NativeRuling ruling : mergedHorizontal) {
            widestLine = Math.max(widestLine, ruling.length());
        }

        List<Float> positions = new LinkedList<>();
        for (NativeRuling ruling : mergedHorizontal) {
            if (ruling.length() >= widestLine * ROW_LINE_COVERAGE) {
                positions.add(ruling.getPosition());
            }
        }

        List<Float> boundaries = NativeGeometryUtil.enforceMinimumBandWidth(
                NativeGeometryUtil.clusterPositions(positions, POSITION_TOLERANCE), MIN_ROW_HEIGHT);

        if (boundaries.size() >= policy.getMinimumRows() + 1) {
            return boundaries;
        }

        // The statement rules its columns but not its rows: every vertical stroke starts and ends on a
        // row boundary, so the endpoints shared by several strokes are the row separations.
        List<Float> endpoints = new LinkedList<>();
        for (NativeRuling ruling : page.getVerticalRulings()) {
            endpoints.add(ruling.getStart());
            endpoints.add(ruling.getEnd());
        }

        List<Float> inferred = NativeGeometryUtil.enforceMinimumBandWidth(
                NativeGeometryUtil.clusterPositions(endpoints, POSITION_TOLERANCE, INFERRED_BOUNDARY_SUPPORT),
                MIN_ROW_HEIGHT);

        return inferred.size() > boundaries.size() ? inferred : boundaries;
    }

    /**
     * Column boundaries for one grid, preferring real vertical rulings and falling back to the column
     * separations that the horizontal strokes of that grid imply.
     */
    private List<Float> columnBoundaries(NativePdfPage page,
                                         List<NativeRuling> mergedVertical,
                                         float top,
                                         float bottom,
                                         NativeExtractionPolicy policy) {
        float height = bottom - top;

        List<Float> positions = new LinkedList<>();
        for (NativeRuling ruling : mergedVertical) {
            if (ruling.overlap(top, bottom) >= height * COLUMN_LINE_COVERAGE) {
                positions.add(ruling.getPosition());
            }
        }

        List<Float> boundaries = NativeGeometryUtil.enforceMinimumBandWidth(
                NativeGeometryUtil.clusterPositions(positions, POSITION_TOLERANCE), MIN_COLUMN_WIDTH);

        if (boundaries.size() >= policy.getMinimumColumns() + 1) {
            return boundaries;
        }

        List<Float> endpoints = new LinkedList<>();
        for (NativeRuling ruling : page.getHorizontalRulings()) {
            if (ruling.getPosition() < top - POSITION_TOLERANCE || ruling.getPosition() > bottom + POSITION_TOLERANCE) {
                continue;
            }
            endpoints.add(ruling.getStart());
            endpoints.add(ruling.getEnd());
        }

        List<Float> inferred = NativeGeometryUtil.enforceMinimumBandWidth(
                NativeGeometryUtil.clusterPositions(endpoints, POSITION_TOLERANCE, INFERRED_BOUNDARY_SUPPORT),
                MIN_COLUMN_WIDTH);

        return inferred.size() > boundaries.size() ? inferred : boundaries;
    }

    /**
     * Splits the row boundaries of a page into separate grids whenever two consecutive boundaries are
     * further apart than a single row may be.
     */
    private List<List<Float>> splitIntoGrids(List<Float> rowBoundaries, float maximumRowGap) {
        List<List<Float>> grids = new LinkedList<>();
        List<Float> current = new ArrayList<>();

        for (Float boundary : rowBoundaries) {
            if (!current.isEmpty() && boundary - current.get(current.size() - 1) > maximumRowGap) {
                grids.add(current);
                current = new ArrayList<>();
            }
            current.add(boundary);
        }
        if (!current.isEmpty()) {
            grids.add(current);
        }

        return grids;
    }

    private Table buildTable(NativePdfPage page,
                             List<Float> rowBoundaries,
                             List<NativeRuling> mergedVertical,
                             NativeExtractionPolicy policy) {
        float top = rowBoundaries.get(0);
        float bottom = rowBoundaries.get(rowBoundaries.size() - 1);
        if (bottom - top <= 0) {
            return null;
        }

        List<Float> columnBoundaries = columnBoundaries(page, mergedVertical, top, bottom, policy);
        if (columnBoundaries.size() < policy.getMinimumColumns() + 1) {
            return null;
        }

        List<NativeCell> cells = new LinkedList<>();
        for (int row = 0; row < rowBoundaries.size() - 1; row++) {
            float rowTop = rowBoundaries.get(row);
            float rowBottom = rowBoundaries.get(row + 1);
            for (int column = 0; column < columnBoundaries.size() - 1; column++) {
                cells.add(new NativeCell(row, column, new NativeBox(
                        columnBoundaries.get(column), rowTop, columnBoundaries.get(column + 1), rowBottom)));
            }
        }

        return NativeTableAssembler.assemble(page.getPageNumber(), cells, page.getWords(), columnBoundaries);
    }
}

