/**
 * A line starts a transaction row when one of its leading tokens - or the leading three tokens
 * joined, for formats that split "01 Apr 2024" - parses as a date with the very same rules the
 * transaction parser uses.
 */
private List<Integer> selectTransactionLines(List<TextLineGroup> lines) {
    List<Integer> selected = new LinkedList<>();
    for (int index = 0; index < lines.size(); index++) {
        TextLineGroup line = lines.get(index);
        if (line.words.isEmpty()) {
            continue;
        }
        if (startsWithDate(line)) {
            selected.add(index);
        }
    }
    return selected;
}

private boolean startsWithDate(TextLineGroup line) {
    int leadingTokens = Math.min(LEADING_TOKENS_TO_PROBE, line.words.size());
    for (int index = 0; index < leadingTokens; index++) {
        if (looksLikeDate(safeContent(line.words.get(index)))) {
            return true;
        }
    }
    if (line.words.size() >= 3) {
        String joined = safeContent(line.words.get(0))
                + safeContent(line.words.get(1))
                + safeContent(line.words.get(2));
        return looksLikeDate(joined);
    }
    return false;
}

private boolean looksLikeDate(String content) {
    if (content == null || content.length() < 5 || content.length() > 12) {
        return false;
    }
    return columnTypeIdentifier != null && columnTypeIdentifier.isDateType(content);
}

/**
 * Finds the column header line of the transaction table. The header is not necessarily above the
 * first selected row - statements that repeat their header per page start a page in the middle of the
 * table - so every non transaction line is considered.
 */
private int findHeaderLine(List<TextLineGroup> lines, List<Integer> transactionLines) {
    int bestLine = -1;
    int bestScore = MIN_HEADER_KEYWORDS - 1;

    for (int index = 0; index < lines.size(); index++) {
        if (transactionLines.contains(index)) {
            continue;
        }
        String content = lines.get(index).content().toLowerCase(Locale.ROOT);
        int score = 0;
        for (String keyword : HEADER_KEYWORDS) {
            if (content.contains(keyword)) {
                score++;
            }
        }
        if (score > bestScore) {
            bestScore = score;
            bestLine = index;
        }
    }

    return bestLine;
}

/**
 * Builds the column boundaries.
 *
 * <p>When a header line is available its own word grouping is by far the most reliable evidence: the
 * gaps between the column labels are the column separations. Otherwise the vertical whitespace
 * corridors shared by all selected rows are used.</p>
 */
private List<Float> detectColumnBoundaries(TextLineGroup header, List<TextLineGroup> rows) {
    float left = Float.MAX_VALUE;
    float right = -Float.MAX_VALUE;
    for (TextLineGroup row : rows) {
        for (Word word : row.words) {
            left = Math.min(left, word.getX1());
            right = Math.max(right, word.getX3());
        }
    }
    if (left >= right) {
        return new ArrayList<>();
    }

    List<Float> boundaries = header == null
            ? corridorBoundaries(rows, left, right)
            : headerBoundaries(header, left, right);

    List<Float> filtered = NativeGeometryUtil.enforceMinimumBandWidth(boundaries, MIN_COLUMN_WIDTH);
    if (filtered.size() >= 2) {
        filtered.set(0, Math.min(filtered.get(0), left));
        filtered.set(filtered.size() - 1, Math.max(right, filtered.get(filtered.size() - 1)));
    }
    return filtered;
}

/**
 * Splits the header line into column labels and puts a boundary in the middle of every gap.
 */
private List<Float> headerBoundaries(TextLineGroup header, float left, float right) {
    List<Float> boundaries = new ArrayList<>();
    boundaries.add(Math.min(left, header.words.isEmpty() ? left : header.words.get(0).getX1()));

    Word previous = null;
    for (Word word : header.words) {
        if (previous != null) {
            float gap = word.getX1() - previous.getX3();
            float threshold = Math.max(MIN_HEADER_LABEL_GAP,
                    (previous.getHeight() == null ? 0f : previous.getHeight()) * HEADER_GAP_HEIGHT_RATIO);
            if (gap > threshold) {
                boundaries.add((previous.getX3() + word.getX1()) / 2f);
            }
        }
        previous = word;
    }

    boundaries.add(right);
    return boundaries;
}

/**
 * Builds the column boundaries out of the vertical whitespace corridors shared by all rows.
 */
private List<Float> corridorBoundaries(List<TextLineGroup> rows, float left, float right) {
    int bucketCount = (int) Math.ceil((right - left) / BUCKET_WIDTH) + 1;
    boolean[] occupied = new boolean[bucketCount];

    for (TextLineGroup row : rows) {
        for (Word word : row.words) {
            int from = bucketOf(word.getX1(), left, bucketCount);
            int to = bucketOf(word.getX3(), left, bucketCount);
            for (int bucket = from; bucket <= to; bucket++) {
                occupied[bucket] = true;
            }
        }
    }

    List<Float> boundaries = new ArrayList<>();
    boundaries.add(left);

    int minimumCorridorBuckets = Math.max(2, Math.round(MIN_CORRIDOR_WIDTH / BUCKET_WIDTH));
    int runStart = -1;
    for (int bucket = 0; bucket < bucketCount; bucket++) {
        if (!occupied[bucket]) {
            if (runStart < 0) {
                runStart = bucket;
            }
            continue;
        }
        if (runStart >= 0) {
            addCorridorBoundary(boundaries, runStart, bucket - 1, minimumCorridorBuckets, left);
            runStart = -1;
        }
    }

    boundaries.add(right);
    return boundaries;
}

