package com.finboost.bank.statement.parser.service.document.extraction.nativetable;

import com.finboost.bank.statement.parser.representation.document.extraction.NativeTableLayout;

import java.util.Collections;
import java.util.List;

/**
 * The state of a native transaction table extraction for one statement.
 *
 * <p>The attempt only holds the native page content; the candidate documents themselves are built one
 * layout at a time by
 * {@link NativeTransactionTableExtractionService#buildCandidate(NativeExtractionAttempt, NativeTableLayout)}
 * so that a rejected candidate can be released before the next one is built. Statements can run into
 * hundreds of pages, materialising every candidate up front would multiply the memory footprint.</p>
 */
public class NativeExtractionAttempt {

    private final boolean supported;
    private final NativeExtractionPolicy policy;
    private final List<NativePdfPage> pages;

    private NativeExtractionAttempt(boolean supported, NativeExtractionPolicy policy, List<NativePdfPage> pages) {
        this.supported = supported;
        this.policy = policy;
        this.pages = pages == null ? Collections.emptyList() : pages;
    }

    /**
     * The bank-format family is not one of the natively supported ones.
     */
    public static NativeExtractionAttempt unsupported() {
        return new NativeExtractionAttempt(false, null, Collections.emptyList());
    }

    /**
     * The bank-format family is supported but no native page content could be read (scanned or rotated
     * statement, unreadable PDF).
     */
    public static NativeExtractionAttempt withoutContent(NativeExtractionPolicy policy) {
        return new NativeExtractionAttempt(true, policy, Collections.emptyList());
    }

    public static NativeExtractionAttempt of(NativeExtractionPolicy policy, List<NativePdfPage> pages) {
        return new NativeExtractionAttempt(true, policy, pages);
    }

    /**
     * @return whether the native path applies to this bank-format family at all
     */
    public boolean isSupported() {
        return supported;
    }

    public NativeExtractionPolicy getPolicy() {
        return policy;
    }

    List<NativePdfPage> getPages() {
        return pages;
    }

    /**
     * @return the native layouts to try, in policy priority order, or an empty list when nothing can be
     * attempted
     */
    public List<NativeTableLayout> getCandidateLayouts() {
        if (!supported || policy == null || pages.isEmpty()) {
            return Collections.emptyList();
        }
        return policy.getCandidateLayouts();
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativetable;

import com.finboost.bank.statement.parser.representation.document.extraction.DocumentExtractionRequest;
import com.finboost.bank.statement.parser.representation.document.extraction.DocumentExtractionResult;
import com.finboost.bank.statement.parser.representation.document.extraction.NativeTableLayout;
import com.finboost.bank.statement.parser.representation.document.extraction.Page;
import com.finboost.bank.statement.parser.representation.document.extraction.Table;
import com.finboost.bank.statement.parser.representation.document.extraction.TransactionExtractionMode;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import java.util.ArrayList;
import java.util.EnumMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Offline (native) transaction table extraction.
 *
 * <p>For the bank-format families registered in {@link NativeExtractionPolicyRegistry} the transaction
 * tables are reconstructed directly from the PDF content stream. The caller obtains an
 * {@link NativeExtractionAttempt}, builds the candidate of one layout at a time, validates it with the
 * shared document analysis, and only invokes the remote ML extraction when no layout works.</p>
 */
@Slf4j
@Service
public class NativeTransactionTableExtractionService {

    private NativeExtractionPolicyRegistry policyRegistry;
    private NativePdfPageReader pageReader;
    private final Map<NativeTableLayout, NativeTableExtractor> extractors = new EnumMap<>(NativeTableLayout.class);

    @Autowired
    public void setPolicyRegistry(NativeExtractionPolicyRegistry policyRegistry) {
        this.policyRegistry = policyRegistry;
    }

    @Autowired
    public void setPageReader(NativePdfPageReader pageReader) {
        this.pageReader = pageReader;
    }

    @Autowired
    public void setTableExtractors(List<NativeTableExtractor> tableExtractors) {
        this.extractors.clear();
        if (tableExtractors != null) {
            for (NativeTableExtractor extractor : tableExtractors) {
                this.extractors.put(extractor.getLayout(), extractor);
            }
        }
    }

    /**
     * @return whether the bank of the request belongs to a natively supported bank-format family
     */
    public boolean isNativelySupported(String bankCode) {
        return policyRegistry.isSupported(bankCode);
    }

    /**
     * Selects the native policy of the statement's bank-format family and reads the native page content.
     *
     * @return the attempt, {@link NativeExtractionAttempt#unsupported()} when the bank-format family is
     * not supported natively
     */
    public NativeExtractionAttempt extract(DocumentExtractionRequest request) {
        if (request == null || request.getStatementFile() == null) {
            return NativeExtractionAttempt.unsupported();
        }

        NativeExtractionPolicy policy = policyRegistry.findPolicy(request.getBankName());
        if (policy == null) {
            return NativeExtractionAttempt.unsupported();
        }

        List<NativePdfPage> pages = pageReader.readPages(request.getStatementFile());
        if (pages.isEmpty()) {
            log.info("Native transaction table extraction not applicable for bank {}, no native page content",
                    policy.getBankCode());
            return NativeExtractionAttempt.withoutContent(policy);
        }

        log.info("Native transaction table extraction will try {} layout(s) for bank {} over {} page(s)",
                policy.getCandidateLayouts().size(), policy.getBankCode(), pages.size());

        return NativeExtractionAttempt.of(policy, pages);
    }

    /**
     * Builds the candidate document of a single native layout.
     *
     * @return the reconstructed document, or {@code null} when the layout did not produce any table
     */
    public DocumentExtractionResult buildCandidate(NativeExtractionAttempt attempt, NativeTableLayout layout) {
        if (attempt == null || layout == null || attempt.getPages().isEmpty()) {
            return null;
        }

        NativeTableExtractor extractor = extractors.get(layout);
        if (extractor == null) {
            log.warn("No native table extractor registered for layout {}", layout);
            return null;
        }

        Map<Integer, Page> pages = new LinkedHashMap<>();
        int tableCount = 0;

        for (NativePdfPage source : attempt.getPages()) {
            NativePdfPage nativePage = source.copyForExtraction();

            List<Table> tables;
            try {
                tables = extractor.extractTables(nativePage, attempt.getPolicy());
            } catch (Exception e) {
                log.warn("Native {} extraction failed on page {}: {}",
                        layout, nativePage.getPageNumber(), e.getMessage());
                return null;
            }

            Map<Integer, Table> tableMap = new LinkedHashMap<>();
            int tableIndex = 0;
            for (Table table : tables) {
                tableMap.put(tableIndex++, table);
            }
            tableCount += tableMap.size();

            Page page = new Page();
            page.setPageNumber(nativePage.getPageNumber());
            page.setWidth((double) nativePage.getWidth());
            page.setHeight((double) nativePage.getHeight());
            page.setWords(new ArrayList<>(nativePage.getWords()));
            page.setContent(nativePage.getTextContent());
            page.setTables(tableMap);

            pages.put(page.getPageNumber(), page);
        }

        if (tableCount == 0) {
            log.debug("Native {} layout produced no table", layout);
            return null;
        }

        DocumentExtractionResult result = new DocumentExtractionResult();
        result.setPages(pages);
        result.setNoOfPages(pages.size());
        result.setTransactionExtractionMode(TransactionExtractionMode.NATIVE);
        result.setNativeTableLayout(layout);

        return result;
    }
}

arguments.newString:
/**
 * Builds one native candidate at a time, analyses it with the shared pipeline and returns the first
 * usable one. Rejected candidates are released before the next layout is attempted.
 */
private DocumentExtractionResult selectNativeResult(NativeExtractionAttempt nativeAttempt,
                                                    DocumentExtractionRequest request) {
    for (NativeTableLayout layout : nativeAttempt.getCandidateLayouts()) {
        DocumentExtractionResult result;
        try {
            result = nativeTransactionTableExtractionService.buildCandidate(nativeAttempt, layout);
        } catch (Exception e) {
            log.warn("Native {} candidate could not be built: {}", layout, e.getMessage());
            continue;
        }
        if (result == null) {
            continue;
        }

        try {
            documentAnalysisPipeline.analyze(result, request, result.getNoOfPages() == null ? 0 : result.getNoOfPages());
        } catch (Exception e) {
            log.warn("Native {} candidate could not be analysed: {}", layout, e.getMessage());
            continue;
        }

        if (nativeExtractionValidator.isUsable(result)) {
            result.setTransactionExtractionMode(TransactionExtractionMode.NATIVE);
            result.setNativeTableLayout(layout);
            log.info("Transaction tables extracted natively using the {} layout for bank {}",
                    layout, request.getBankName());
            return result;
        }

        log.info("Native {} candidate rejected for bank {}", layout, request.getBankName());
    }

    return null;
}

