package com.finboost.bank.statement.parser.service.document.extraction.nativetable;

import com.finboost.bank.statement.parser.representation.document.extraction.Word;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

/**
 * A visual text line of a page - or a whole transaction row once its wrapped lines have been folded
 * into it.
 */
public class NativeTextLine {

    private final List<Word> words = new ArrayList<>();
    private float baseline;
    private float top;
    private float bottom;

    NativeTextLine(Word first) {
        this.baseline = safeY4(first);
        this.top = safeY1(first);
        this.bottom = safeY4(first);
        this.words.add(first);
    }

    NativeTextLine(NativeTextLine source) {
        this.baseline = source.baseline;
        this.top = source.top;
        this.bottom = source.bottom;
        this.words.addAll(source.words);
    }

    public List<Word> getWords() {
        return words;
    }

    public float getBaseline() {
        return baseline;
    }

    public float getTop() {
        return top;
    }

    public float getBottom() {
        return bottom;
    }

    void add(Word word) {
        this.top = Math.min(this.top, safeY1(word));
        this.bottom = Math.max(this.bottom, safeY4(word));
        this.words.add(word);
    }

    void merge(NativeTextLine other) {
        this.top = Math.min(this.top, other.top);
        this.bottom = Math.max(this.bottom, other.bottom);
        this.words.addAll(other.words);
    }

    void sortByX() {
        words.sort(Comparator.comparing(word -> word.getX1() == null ? 0f : word.getX1()));
    }

    /**
     * The words of the line joined by single spaces.
     */
    public String content() {
        StringBuilder builder = new StringBuilder();
        for (Word word : words) {
            if (builder.length() > 0) {
                builder.append(' ');
            }
            builder.append(text(word));
        }
        return builder.toString();
    }

    static String text(Word word) {
        String content = word == null ? null : word.getContent();
        return content == null ? "" : content.trim();
    }

    private static float safeY1(Word word) {
        return word.getY1() == null ? 0f : word.getY1();
    }

    private static float safeY4(Word word) {
        return word.getY4() == null ? 0f : word.getY4();
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativetable;

import com.finboost.bank.statement.parser.representation.document.extraction.Word;
import com.finboost.bank.statement.parser.service.document.extraction.post.processor.ColumnTypeIdentifier;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedList;
import java.util.List;

/**
 * Groups the words of a page into visual text lines and recognises the lines that start a transaction.
 *
 * <p>Shared by the text aligned extractor - which turns those lines into table rows - and by the
 * estimation of how many transaction rows a statement contains, which is what makes it possible to tell
 * a faithful native reconstruction from one that silently dropped most rows.</p>
 */
@Slf4j
@Service
public class NativeTextLineGrouper {

    /** Vertical tolerance used to group words into a text line, in inches. */
    private static final float MIN_LINE_TOLERANCE = 0.02f;
    private static final float LINE_TOLERANCE_RATIO = 0.5f;
    /** Number of leading tokens of a line that are probed for a transaction date. */
    private static final int LEADING_TOKENS_TO_PROBE = 2;
    private static final int MIN_DATE_LENGTH = 5;
    private static final int MAX_DATE_LENGTH = 12;

    private ColumnTypeIdentifier columnTypeIdentifier;

    @Autowired
    public void setColumnTypeIdentifier(ColumnTypeIdentifier columnTypeIdentifier) {
        this.columnTypeIdentifier = columnTypeIdentifier;
    }

    /**
     * Groups the words of one page into visual text lines, ordered top to bottom, each line ordered left
     * to right.
     */
    public List<NativeTextLine> groupIntoLines(List<Word> words) {
        List<NativeTextLine> lines = new LinkedList<>();
        if (words == null || words.isEmpty()) {
            return lines;
        }

        List<Word> sorted = new ArrayList<>(words);
        sorted.sort(Comparator
                .comparing((Word word) -> word.getY4() == null ? 0f : word.getY4())
                .thenComparing(word -> word.getX1() == null ? 0f : word.getX1()));

        NativeTextLine current = null;
        for (Word word : sorted) {
            float baseline = word.getY4() == null ? 0f : word.getY4();
            float tolerance = Math.max(MIN_LINE_TOLERANCE,
                    (word.getHeight() == null ? 0f : word.getHeight()) * LINE_TOLERANCE_RATIO);
            if (current == null || Math.abs(baseline - current.getBaseline()) > tolerance) {
                current = new NativeTextLine(word);
                lines.add(current);
            } else {
                current.add(word);
            }
        }

        for (NativeTextLine line : lines) {
            line.sortByX();
        }

        return lines;
    }

    /**
     * A line starts a transaction when one of its leading tokens - or the leading three tokens joined,
     * for formats that split "01 Apr 2024" - is recognised as a date by the very same rules the column
     * typing uses.
     */
    public boolean startsWithTransactionDate(NativeTextLine line) {
        if (line == null || line.getWords().isEmpty()) {
            return false;
        }

        int leadingTokens = Math.min(LEADING_TOKENS_TO_PROBE, line.getWords().size());
        for (int index = 0; index < leadingTokens; index++) {
            if (looksLikeDate(NativeTextLine.text(line.getWords().get(index)))) {
                return true;
            }
        }

        if (line.getWords().size() >= 3) {
            String joined = NativeTextLine.text(line.getWords().get(0))
                    + NativeTextLine.text(line.getWords().get(1))
                    + NativeTextLine.text(line.getWords().get(2));
            return looksLikeDate(joined);
        }

        return false;
    }

    /**
     * Estimates how many transaction rows the statement holds by counting the text lines that start with
     * a transaction date, across every page.
     *
     * <p>The estimate is layout independent, which makes it a fair yardstick for judging whether a
     * reconstructed table actually captured the whole statement.</p>
     */
    public int estimateTransactionRows(List<NativePdfPage> pages) {
        if (pages == null || pages.isEmpty()) {
            return 0;
        }

        int count = 0;
        for (NativePdfPage page : pages) {
            for (NativeTextLine line : groupIntoLines(page.getWords())) {
                if (startsWithTransactionDate(line)) {
                    count++;
                }
            }
        }
        return count;
    }

    private boolean looksLikeDate(String content) {
        if (content == null || content.length() < MIN_DATE_LENGTH || content.length() > MAX_DATE_LENGTH) {
            return false;
        }
        return columnTypeIdentifier != null && columnTypeIdentifier.isDateType(content);
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativetable;

import com.finboost.bank.statement.parser.representation.document.extraction.NativeTableLayout;
import com.finboost.bank.statement.parser.representation.document.extraction.Table;
import com.finboost.bank.statement.parser.representation.document.extraction.Word;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import java.util.ArrayList;
import java.util.LinkedList;
import java.util.List;
import java.util.Locale;

/**
 * Rebuilds transaction tables for statements whose transaction table carries no usable geometry.
 *
 * <p>Rows are <em>selected</em> from the text layer: a text line that starts with a transaction date
 * begins a transaction row, and the wrapped lines that follow it are folded back into that row. Columns
 * come from the header line - the gaps between its column labels are the column separations - or, when no
 * header can be found, from the vertical whitespace corridors that the selected rows share.</p>
 */
@Slf4j
@Service
public class TextAlignedRowSelectedTableExtractor implements NativeTableExtractor {

    private static final String[] HEADER_KEYWORDS = {
            "date", "narration", "description", "particulars", "remarks", "detail",
            "withdrawal", "deposit", "debit", "credit", "amount", "balance",
            "chq", "cheque", "ref", "instrument", "transaction", "value"
    };

    /** Width of one occupancy bucket, in inches. */
    private static final float BUCKET_WIDTH = 0.01f;
    /** Minimum width of a whitespace corridor that separates two columns, in inches. */
    private static final float MIN_CORRIDOR_WIDTH = 0.055f;
    private static final float MIN_COLUMN_WIDTH = 0.10f;
    private static final int MIN_HEADER_KEYWORDS = 2;
    /** Minimum gap between two header labels, in inches. */
    private static final float MIN_HEADER_LABEL_GAP = 0.055f;

    private NativeTextLineGrouper lineGrouper;

    @Autowired
    public void setLineGrouper(NativeTextLineGrouper lineGrouper) {
        this.lineGrouper = lineGrouper;
    }

    @Override
    public NativeTableLayout getLayout() {
        return NativeTableLayout.TEXT_ALIGNED_ROW_SELECTED;
    }

    @Override
    public List<Table> extractTables(NativePdfPage page, NativeExtractionPolicy policy) {
        List<Table> tables = new LinkedList<>();
        if (page == null || !page.hasText()) {
            return tables;
        }

        List<NativeTextLine> lines = lineGrouper.groupIntoLines(page.getWords());
        if (lines.size() < policy.getMinimumRows()) {
            return tables;
        }

        List<Integer> transactionLines = selectTransactionLines(lines);
        if (transactionLines.size() < Math.max(2, policy.getMinimumRows() - 1)) {
            return tables;
        }

        int headerLine = findHeaderLine(lines, transactionLines);
        List<NativeTextLine> rows = buildRows(lines, transactionLines, headerLine);

        List<Float> columnBoundaries = detectColumnBoundaries(
                headerLine >= 0 ? lines.get(headerLine) : null, rows);
        if (columnBoundaries.size() < policy.getMinimumColumns() + 1) {
            return tables;
        }

        List<NativeCell> cells = buildCells(rows, columnBoundaries);

        Table table = NativeTableAssembler.assemble(page.getPageNumber(), cells, page.getWords(), columnBoundaries);
        if (table != null) {
            tables.add(table);
        }
        return tables;
    }

    private List<Integer> selectTransactionLines(List<NativeTextLine> lines) {
        List<Integer> selected = new LinkedList<>();
        for (int index = 0; index < lines.size(); index++) {
            if (lineGrouper.startsWithTransactionDate(lines.get(index))) {
                selected.add(index);
            }
        }
        return selected;
    }

    /**
     * Builds the table rows: the header line first (so that the header identification downstream sees it
     * where it expects it) followed by one row per selected transaction line, with every wrapped
     * continuation line folded into the row that owns it.
     */
    private List<NativeTextLine> buildRows(List<NativeTextLine> lines, List<Integer> transactionLines, int headerLine) {
        List<NativeTextLine> rows = new ArrayList<>();
        if (headerLine >= 0) {
            rows.add(new NativeTextLine(lines.get(headerLine)));
        }

        for (int index = 0; index < transactionLines.size(); index++) {
            int start = transactionLines.get(index);
            int end = index + 1 < transactionLines.size() ? transactionLines.get(index + 1) : lines.size();
            NativeTextLine row = new NativeTextLine(lines.get(start));
            for (int continuation = start + 1; continuation < end; continuation++) {
                if (continuation == headerLine) {
                    continue;
                }
                row.merge(lines.get(continuation));
            }
            rows.add(row);
        }

        return rows;
    }

    private List<NativeCell> buildCells(List<NativeTextLine> rows, List<Float> columnBoundaries) {
        List<NativeCell> cells = new LinkedList<>();
        int lastColumn = columnBoundaries.size() - 2;

        for (int rowIndex = 0; rowIndex < rows.size(); rowIndex++) {
            NativeTextLine row = rows.get(rowIndex);
            for (int column = 0; column <= lastColumn; column++) {
                float left = columnBoundaries.get(column);
                float right = columnBoundaries.get(column + 1);

                List<Word> cellWords = new LinkedList<>();
                for (Word word : row.getWords()) {
                    float centerX = (word.getX1() + word.getX3()) / 2f;
                    if (centerX >= left && (centerX < right || (column == lastColumn && centerX <= right))) {
                        cellWords.add(word);
                    }
                }

                cells.add(new NativeCell(rowIndex, column,
                        new NativeBox(left, row.getTop(), right, row.getBottom()), cellWords));
            }
        }

        return cells;
    }

    /**
     * Finds the column header line of the transaction table. The header is not necessarily above the
     * first selected row - statements that repeat their header per page start a page in the middle of the
     * table - so every non transaction line is considered.
     */
    private int findHeaderLine(List<NativeTextLine> lines, List<Integer> transactionLines) {
        int bestLine = -1;
        int bestScore = MIN_HEADER_KEYWORDS - 1;

        for (int index = 0; index < lines.size(); index++) {
            if (transactionLines.contains(index)) {
                continue;
            }
            String content = lines.get(index).content().toLowerCase(Locale.ROOT);
            int score = 0;
            for (String keyword : HEADER_KEYWORDS) {
                if (content.contains(keyword)) {
                    score++;
                }
            }
            if (score > bestScore) {
                bestScore = score;
                bestLine = index;
            }
        }

        return bestLine;
    }

    private List<Float> detectColumnBoundaries(NativeTextLine header, List<NativeTextLine> rows) {
        float left = Float.MAX_VALUE;
        float right = -Float.MAX_VALUE;
        for (NativeTextLine row : rows) {
            for (Word word : row.getWords()) {
                left = Math.min(left, word.getX1());
                right = Math.max(right, word.getX3());
            }
        }
        if (left >= right) {
            return new ArrayList<>();
        }

        List<Float> boundaries = headerBoundaries(header, left, right);
        List<Float> filtered = NativeGeometryUtil.enforceMinimumBandWidth(boundaries, MIN_COLUMN_WIDTH);
        if (filtered.size() < 3) {
            filtered = NativeGeometryUtil.enforceMinimumBandWidth(
                    corridorBoundaries(rows, left, right), MIN_COLUMN_WIDTH);
        }

        if (filtered.size() >= 2) {
            filtered.set(0, Math.min(filtered.get(0), left));
            filtered.set(filtered.size() - 1, Math.max(right, filtered.get(filtered.size() - 1)));
        }
        return filtered;
    }

    /**
     * Splits the header line into column labels and puts a boundary in the middle of every gap.
     */
    private List<Float> headerBoundaries(NativeTextLine header, float left, float right) {
        List<Float> boundaries = new ArrayList<>();
        if (header == null || header.getWords().isEmpty()) {
            return boundaries;
        }

        boundaries.add(Math.min(left, header.getWords().get(0).getX1()));

        Word previous = null;
        for (Word word : header.getWords()) {
            if (previous != null && word.getX1() - previous.getX3() > MIN_HEADER_LABEL_GAP) {
                boundaries.add((previous.getX3() + word.getX1()) / 2f);
            }
            previous = word;
        }

        boundaries.add(right);
        return boundaries;
    }

    /**
     * Builds the column boundaries out of the vertical whitespace corridors shared by all rows.
     */
    private List<Float> corridorBoundaries(List<NativeTextLine> rows, float left, float right) {
        int bucketCount = (int) Math.ceil((right - left) / BUCKET_WIDTH) + 1;
        boolean[] occupied = new boolean[bucketCount];

        for (NativeTextLine row : rows) {
            for (Word word : row.getWords()) {
                int from = bucketOf(word.getX1(), left, bucketCount);
                int to = bucketOf(word.getX3(), left, bucketCount);
                for (int bucket = from; bucket <= to; bucket++) {
                    occupied[bucket] = true;
                }
            }
        }

        List<Float> boundaries = new ArrayList<>();
        boundaries.add(left);

        int minimumCorridorBuckets = Math.max(2, Math.round(MIN_CORRIDOR_WIDTH / BUCKET_WIDTH));
        int runStart = -1;
        for (int bucket = 0; bucket < bucketCount; bucket++) {
            if (!occupied[bucket]) {
                if (runStart < 0) {
                    runStart = bucket;
                }
                continue;
            }
            if (runStart >= 0) {
                if (bucket - runStart >= minimumCorridorBuckets) {
                    boundaries.add(left + ((runStart + bucket - 1) / 2f) * BUCKET_WIDTH);
                }
                runStart = -1;
            }
        }

        boundaries.add(right);
        return boundaries;
    }

    private int bucketOf(float x, float left, int bucketCount) {
        int bucket = Math.round((x - left) / BUCKET_WIDTH);
        if (bucket < 0) {
            return 0;
        }
        return Math.min(bucket, bucketCount - 1);
    }
}

