                headerBoundaries(header, left, right), MIN_COLUMN_WIDTH);

        if (filtered.size() < 3 && context != null && context.hasColumnBoundaryTemplate()) {
            filtered = new ArrayList<>(context.getColumnBoundaryTemplate());
