    best.setdefault(bank, collections.Counter())
    if oks:
        for layout, _ in oks:
            best[bank][layout] += 1
    else:
        best[bank]['NONE'] += 1
for bank in sorted(best):
    print(f"{bank:35s} {dict(best[bank])}")
