import com.finboost.bank.statement.parser.service.document.extraction.nativetable.*;
import com.finboost.bank.statement.parser.service.document.extraction.post.processor.ColumnTypeIdentifier;
import org.springframework.context.annotation.AnnotationConfigApplicationContext;

public class Wire {
    public static void main(String[] a) {
        AnnotationConfigApplicationContext ctx = new AnnotationConfigApplicationContext();
        ctx.register(ColumnTypeIdentifier.class,
                NativeExtractionPolicyRegistry.class, NativePdfPageReader.class, NativeWordExtractor.class,
                NativeTextLineGrouper.class, BorderedGridTableExtractor.class, BoxGuidedTableExtractor.class,
                TextAlignedRowSelectedTableExtractor.class, NativeTransactionTableExtractionService.class,
                NativeExtractionValidator.class);
        ctx.refresh();
        NativeTransactionTableExtractionService svc = ctx.getBean(NativeTransactionTableExtractionService.class);
        System.out.println("native beans wired ok");
        System.out.println("policy HDFC   = " + ctx.getBean(NativeExtractionPolicyRegistry.class).findPolicy("HDFC"));
        System.out.println("policy hdfc   = " + ctx.getBean(NativeExtractionPolicyRegistry.class).findPolicy(" hdfc "));
        System.out.println("policy GS     = " + ctx.getBean(NativeExtractionPolicyRegistry.class).findPolicy("GS_Mahanagar_Co_Op_Bank"));
        System.out.println("policy DUMMY  = " + ctx.getBean(NativeExtractionPolicyRegistry.class).findPolicy("DUMMY_BANK"));
        com.finboost.bank.statement.parser.representation.document.extraction.DocumentExtractionRequest req =
                new com.finboost.bank.statement.parser.representation.document.extraction.DocumentExtractionRequest();
        req.setStatementFile(new java.io.File("/app/src/test/resources/pdf-samples-latest/SBI/format1.pdf"));
        req.setBankName("SBI");
        NativeExtractionAttempt att = svc.extract(req);
        System.out.println("attempt supported=" + att.isSupported() + " layouts=" + att.getCandidateLayouts() + " expectedRows=" + att.getEstimatedTransactionRows());
        System.out.println("candidate=" + (svc.buildCandidate(att, att.getCandidateLayouts().get(0)) != null));
        req.setBankName("UNKNOWN_BANK");
        System.out.println("unknown supported=" + svc.extract(req).isSupported());
        ctx.close();
    }
}
